                                        var dthen   = new Date(myTargetDate);
                                        var dnow    = new Date();
                                        ddiff       = new Date(dthen-dnow);
                                        gsecs       = Math.floor(ddiff.valueOf()/1000);
                                        CountBack(myDiv,gsecs);
                                    }
                                    function Calcage(secs, num1, num2){
                                        var s = ((Math.floor(secs/num1))%num2).toString();
                                        if (s.length < 2){
                                            s = "0" + s;
                                        }
                                        var n = s.split("");
                                        /* n2 = three number, n3 = four number */
                                        if (typeof(n[2])=="undefined") {
                                            return "<span>" + n[0] + "</span><span>" + n[1] + "</span>";
                                        } else {
                                            return "<span>" + n[0] + "</span><span>" + n[1] + "</span><span>" + n[2] + "</span>";
                                        }
                                    }
                                    function CountBack(myDiv, secs){
                                        var DisplayStr;
                                        var DisplayFormat = "<span class='three-dots' >...</span><span class='dias'>%%D%%</span><span class='three-dots' >...</span>";
                                            DisplayFormat += "<span class='horas'>%%H%%</span><span class='three-dots' >...</span>";
                                            DisplayFormat += "<span class='minutos'>%%M%%</span><span class='three-dots' >...</span>";
                                            DisplayFormat += "<span class='segundos'>%%S%%</span>";

                                        DisplayStr = DisplayFormat.replace(/%%D%%/g, Calcage(secs,86400,100000));
                                        DisplayStr = DisplayStr.replace(/%%H%%/g,    Calcage(secs,3600,24));
                                        DisplayStr = DisplayStr.replace(/%%M%%/g,    Calcage(secs,60,60));
                                        DisplayStr = DisplayStr.replace(/%%S%%/g,    Calcage(secs,1,60));
                                        if(secs > 0){
                                            document.getElementById(myDiv).innerHTML = DisplayStr;
                                            setTimeout("CountBack('" + myDiv + "'," + (secs-1) + ");", 990);
