    function abrirWhatsApp(nomeProduto) {
        var mensagem = nomeProduto 
            ? "Olá! Vi que o produto *" + nomeProduto + "* está indisponível no site e gostaria de saber previsão de reposição ou alternativas." 
            : "Olá! Gostaria de consultar a previsão de reposição ou alternativas de um produto do site.";
        var url = "https://wa.me/" + telefone + "?text=" + encodeURIComponent(mensagem);
        window.open(url, '_blank');
    }

    var observer = new MutationObserver(function() {
