    });

    function atualizarProdutosIndisponiveis() {
        observer.disconnect();

        try {
            var botaoComprar = document.querySelector('.action.tocart.primary:not(.disabled)');
            var estilosComprar = botaoComprar ? window.getComputedStyle(botaoComprar) : null;

            // 1. VITRINE / CARDS DE PRODUTOS
            var cards = document.querySelectorAll('.product-item-info:not([data-indisp-ok])');
            cards.forEach(function(card) {
                card.setAttribute('data-indisp-ok', 'true');
                var btnEstoque = card.querySelector('.stock.unavailable, .action.tocart.disabled');
                if (!btnEstoque) return;

                var textoAtual = (btnEstoque.innerText || btnEstoque.textContent || "").trim().toLowerCase();
                if (textoAtual.includes("fora de estoque") || textoAtual.includes("indisponível")) {
                    btnEstoque.removeAttribute('disabled');
                    btnEstoque.classList.remove('disabled');

                    if (estilosComprar) {
                        btnEstoque.style.setProperty('height', estilosComprar.height, 'important');
                        btnEstoque.style.setProperty('border-radius', estilosComprar.borderRadius, 'important');
                        btnEstoque.style.setProperty('font-size', estilosComprar.fontSize, 'important');
                    }

                    card.querySelectorAll('a, button').forEach(function(el) {
                        if ((el.textContent || "").trim().toLowerCase().includes("comparar")) {
                            el.style.setProperty('display', 'none', 'important');
                        }
                    });

                    var containerPai = btnEstoque.parentElement;
                    if (containerPai && !containerPai.querySelector('.aviso-indisponivel-custom')) {
                        var aviso = document.createElement('div');
                        aviso.className = 'aviso-indisponivel-custom';
                        aviso.textContent = 'Produto indisponível';
                        containerPai.insertBefore(aviso, btnEstoque);
                    }

                    btnEstoque.innerHTML = iconeWpp + '<span>Consulte aqui</span>';

                    btnEstoque.addEventListener('click', function(e) {
                        e.preventDefault();
                        e.stopPropagation();
                        var linkNome = card.querySelector('.product-item-link');
                        var nomeProduto = linkNome ? linkNome.textContent.trim() : "";
                        abrirWhatsApp(nomeProduto);
                    });
                }
            });

            // 2. PÁGINA INTERNA DO PRODUTO
            var infoMain = document.querySelector('.catalog-product-view .product-info-main:not([data-indisp-ok])');
            if (infoMain) {
                var tagStatus = infoMain.querySelector('.product-info-stock-sku .stock.unavailable');
                if (tagStatus) {
                    infoMain.setAttribute('data-indisp-ok', 'true');
                    tagStatus.innerHTML = '<span>Indisponível</span>';

                    infoMain.querySelectorAll('a, button').forEach(function(item) {
                        var txt = (item.textContent || "").trim().toLowerCase();
                        if (txt.includes("me avise") || txt.includes("comparar")) {
                            var alvoOcultar = item.closest('.product.alert, .product-alert, .product-addto-links') || item;
                            alvoOcultar.style.setProperty('display', 'none', 'important');
