                        '<div class="card-indisp-subtitulo">Quer saber previsão de reposição ou alternativas? Fale com nossa equipe.</div>' +
                        '<button type="button" class="card-indisp-botao">' + iconeWpp + '<span>Entrar em contato</span></button>';

                    cardInterno.querySelector('.card-indisp-botao').addEventListener('click', function(e) {
                        e.preventDefault();
                        var tituloPagina = document.querySelector('.page-title span');
                        var nomeProduto = tituloPagina ? tituloPagina.textContent.trim() : "";
                        abrirWhatsApp(nomeProduto);
                    });

                    var linhaStatus = infoMain.querySelector('.product-info-stock-sku');
                    var ancoraPai = linhaStatus ? (linhaStatus.closest('.product-info-price') || linhaStatus) : null;

                    if (ancoraPai && ancoraPai.parentNode) {
                        ancoraPai.parentNode.insertBefore(cardInterno, ancoraPai.nextSibling);
                    } else {
                        infoMain.insertBefore(cardInterno, infoMain.firstChild);
                    }
                }
            }
        } finally {
            observer.observe(document.body, { childList: true, subtree: true });
        }
    }

    atualizarProdutosIndisponiveis();
});

