                foundBrands[url] = brands[url];
            }
        }
        if (!Object.keys(foundBrands).length) {
            resDropDown.style.display = "none";
        } else {
            var result = '';
            for(var url in foundBrands) {
                result += '<a href="' + url +'">'
                    + foundBrands[url] + '</a>';
            }
            resDropDown.style.display = "block";
            resDropDown.innerHTML = result;
        }
    }

