(function() {
    'use strict';
    
    function isVisible(element) {
        // Verifica se o elemento está visível
        if (!element) return false;
        
        const style = window.getComputedStyle(element);
        if (style.display === 'none' || style.visibility === 'hidden') {
            return false;
        }
        
        // Verifica se o elemento pai tem hide-element
        let parent = element.closest('.field');
        if (parent && parent.classList.contains('hide-element')) {
            return false;
        }
        
        // Verifica se o elemento tem dimensões
        const rect = element.getBoundingClientRect();
        return rect.width > 0 && rect.height > 0;
    }
    
    function fixTabOrder() {
        // Selecionar todos os campos interativos do formulário
        const fieldset = document.querySelector('.fieldset.create.info');
        if (!fieldset) return;
        
        const allFields = fieldset.querySelectorAll('input, select, button');
        const visibleFields = [];
        
        // Filtrar apenas campos visíveis
        allFields.forEach(function(field) {
            if (field.type !== 'hidden' && isVisible(field)) {
                visibleFields.push(field);
            }
        });
        
        // Array para armazenar campos com suas posições
        const fieldsWithPosition = [];
        
        visibleFields.forEach(function(field) {
            const rect = field.getBoundingClientRect();
            const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
            const scrollLeft = window.pageXOffset || document.documentElement.scrollLeft;
            
            fieldsWithPosition.push({
                element: field,
                top: rect.top + scrollTop,
                left: rect.left + scrollLeft
            });
        });
        
        // Ordenar por posição: primeiro por top (linha), depois por left (coluna)
        fieldsWithPosition.sort(function(a, b) {
            // Tolerância de 10px para considerar elementos na mesma linha
            const rowTolerance = 10;
            
            if (Math.abs(a.top - b.top) <= rowTolerance) {
                // Mesma linha, ordenar por coluna (left)
                return a.left - b.left;
            }
            // Linhas diferentes, ordenar por linha (top)
            return a.top - b.top;
        });
        
        // Aplicar tabindex sequencial
        fieldsWithPosition.forEach(function(item, index) {
            item.element.setAttribute('tabindex', index + 1);
        });
        
        console.log('Ordem de TAB corrigida para ' + fieldsWithPosition.length + ' campos');
    }
    
    // Executar quando o DOM estiver pronto
    function init() {
        setTimeout(fixTabOrder, 100);
        
        // Reexecutar quando campos forem mostrados/escondidos
        const personType = document.getElementById('person_type');
        if (personType) {
            personType.addEventListener('change', function() {
                setTimeout(fixTabOrder, 100);
            });
        }
        
        // Reexecutar se houver mudanças no formulário
