document.querySelectorAll(".right-to-left, .left-to-right").forEach((track) => {

    // Duplicate content only once
    if (!track.dataset.clone) {
        track.innerHTML += track.innerHTML;
        track.dataset.clone = "true";
    }

    let x = track.classList.contains("left-to-right")
        ? -(track.scrollWidth / 3)
        : 0;

    const speed = 0.5; // Increase for faster movement

    function animate() {
        if (track.classList.contains("right-to-left")) {
            x -= speed;

            if (Math.abs(x) >= track.scrollWidth / 3) {
                x = 0;
            }
        } else {
            x += speed;

            if (x >= 0) {
                x = -(track.scrollWidth / 3);
            }
        }

        track.style.transform = `translateX(${x}px)`;
        requestAnimationFrame(animate);
    }

    animate();
});

