var imgs = new Array('https://4stonebuildings.com/wp-content/uploads/2026/06/GeneralViews-132-2400x1600.jpg','https://4stonebuildings.com/wp-content/uploads/2023/09/Generalviews-185-2400x1600.jpg','https://4stonebuildings.com/wp-content/uploads/2026/06/GeneralViews-156-2400x1600.jpg','https://4stonebuildings.com/wp-content/uploads/2026/06/Generalviews-168-2400x1600.jpg','https://4stonebuildings.com/wp-content/uploads/2026/06/Generalviews-116-2400x1600.jpg');
   var currentBgIndex = 1; // Start with the second image
    var currentBg = '#bg1';
    var nextBg = '#bg2';

    jQuery(document).ready(function() {
        // Initially set the first image on bg1 and show it
        jQuery(currentBg).css('background-image', 'url(' + imgs[0] + ')').show();

        // Preload the second image on bg2 but keep it hidden
        jQuery(nextBg).css('background-image', 'url(' + imgs[1] + ')').hide();

        // Start the transition cycle
        setInterval(changeBackgroundWithFade, 5000);
    });

    function changeBackgroundWithFade() {
        // Set the next image on the next background
        jQuery(nextBg).css('background-image', 'url(' + imgs[currentBgIndex] + ')');

        // Fade in the next background while fading out the current one
        jQuery(nextBg).fadeIn(1500);
        jQuery(currentBg).fadeOut(1500, function() {
            // After the fade out, switch the roles of bg1 and bg2
            var temp = currentBg;
            currentBg = nextBg;
            nextBg = temp;

            // Set the next image index and prepare the nextBg for the next cycle
            currentBgIndex = (currentBgIndex + 1) % imgs.length;
            jQuery(nextBg).hide(); // Ensure nextBg is hidden and ready for next fade in
        });
    }

