(function () {
  var header = document.getElementById('site-header');
  var toggle = document.getElementById('menu-toggle');
  var mobileMenu = document.getElementById('mobile-menu');

  if (!header || !toggle || !mobileMenu) return;

  function setScrolledState() {
    if (window.scrollY > 20) {
      header.classList.add('is-scrolled');
    } else {
      header.classList.remove('is-scrolled');
    }
  }

  function closeMenu() {
    mobileMenu.classList.remove('is-open');
    toggle.classList.remove('is-active');
    toggle.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
  }

  function openMenu() {
    mobileMenu.classList.add('is-open');
    toggle.classList.add('is-active');
    toggle.setAttribute('aria-expanded', 'true');
    document.body.style.overflow = 'hidden';
  }

  toggle.addEventListener('click', function () {
    if (mobileMenu.classList.contains('is-open')) {
      closeMenu();
    } else {
      openMenu();
    }
  });

  window.addEventListener('resize', function () {
    if (window.innerWidth >= 1100) {
      closeMenu();
    }
  });

  mobileMenu.querySelectorAll('a').forEach(function (link) {
    link.addEventListener('click', function () {
      closeMenu();
    });
  });

  window.addEventListener('scroll', setScrolledState);
  setScrolledState();
})();

(function () {
      var banner = document.getElementById('cookie-banner');
      var panel = document.getElementById('cookie-panel');
      var acceptBtn = document.getElementById('cookie-accept');
      var refuseBtn = document.getElementById('cookie-refuse');
      var customizeBtn = document.getElementById('cookie-customize');
      var savePreferencesBtn = document.getElementById('cookie-save-preferences');
      var closePanelBtn = document.getElementById('cookie-close-panel');
      var analyticsToggle = document.getElementById('cookie-analytics-toggle');
      var settingsLink = document.getElementById('cookie-settings-link');

      var CONSENT_COOKIE_NAME = 'cookie_consent';
      var CONSENT_DURATION_DAYS = 180;
      var GA4_MEASUREMENT_ID = 'G-XXXXXXXXXX';

      if (!banner) return;

      function setCookie(name, value, days) {
        var expires = '';
        if (days) {
          var date = new Date();
          date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
          expires = '; expires=' + date.toUTCString();
        }
        document.cookie = name + '=' + encodeURIComponent(value) + expires + '; path=/; SameSite=Lax';
      }

      function getCookie(name) {
        var nameEQ = name + '=';
        var cookies = document.cookie.split(';');

        for (var i = 0; i < cookies.length; i++) {
          var c = cookies[i];
          while (c.charAt(0) === ' ') {
            c = c.substring(1, c.length);
          }
          if (c.indexOf(nameEQ) === 0) {
            return decodeURIComponent(c.substring(nameEQ.length, c.length));
          }
        }
        return null;
      }

      function deleteCookie(name) {
        document.cookie = name + '=; Max-Age=0; path=/; SameSite=Lax';
      }

      function hideBanner() {
        banner.classList.add('cookie-hidden');
      }

      function showBanner() {
        banner.classList.remove('cookie-hidden');
      }

      function showPanel() {
        if (panel) panel.classList.remove('cookie-hidden');
      }

      function hidePanel() {
        if (panel) panel.classList.add('cookie-hidden');
      }

      function loadGA4() {
        if (window.ga4Loaded) return;
        window.ga4Loaded = true;

        window.dataLayer = window.dataLayer || [];
        function gtag(){ dataLayer.push(arguments); }
        window.gtag = gtag;

        gtag('js', new Date());
        gtag('config', GA4_MEASUREMENT_ID, {
          anonymize_ip: true
        });

        var script = document.createElement('script');
        script.async = true;
        script.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(GA4_MEASUREMENT_ID);
        document.head.appendChild(script);
      }

      function applyConsent(value) {
        if (value === 'accepted') {
          hideBanner();
          hidePanel();
          if (analyticsToggle) analyticsToggle.checked = true;
          loadGA4();
          return;

        }

        if (value === 'refused') {
          hideBanner();
          hidePanel();
          if (analyticsToggle) analyticsToggle.checked = false;
          return;
        }

        showBanner();
        hidePanel();
      }

      var savedConsent = getCookie(CONSENT_COOKIE_NAME);
      applyConsent(savedConsent);

      if (acceptBtn) {
        acceptBtn.addEventListener('click', function () {
          setCookie(CONSENT_COOKIE_NAME, 'accepted', CONSENT_DURATION_DAYS);
          applyConsent('accepted');
        });
      }

      if (refuseBtn) {
        refuseBtn.addEventListener('click', function () {
          setCookie(CONSENT_COOKIE_NAME, 'refused', CONSENT_DURATION_DAYS);
          applyConsent('refused');
        });
      }

      if (customizeBtn) {
        customizeBtn.addEventListener('click', function () {
          var currentConsent = getCookie(CONSENT_COOKIE_NAME);
          if (analyticsToggle) {
            analyticsToggle.checked = currentConsent === 'accepted';
          }
          showPanel();
        });
      }

      if (savePreferencesBtn) {
        savePreferencesBtn.addEventListener('click', function () {
          if (analyticsToggle && analyticsToggle.checked) {
            setCookie(CONSENT_COOKIE_NAME, 'accepted', CONSENT_DURATION_DAYS);
            applyConsent('accepted');
          } else {
            setCookie(CONSENT_COOKIE_NAME, 'refused', CONSENT_DURATION_DAYS);
            applyConsent('refused');
          }
        });
      }

      if (closePanelBtn) {
        closePanelBtn.addEventListener('click', function () {
          hidePanel();
        });
      }

      if (settingsLink) {
        settingsLink.addEventListener('click', function (e) {
          e.preventDefault();
          var currentConsent = getCookie(CONSENT_COOKIE_NAME);
          if (analyticsToggle) {
            analyticsToggle.checked = currentConsent === 'accepted';
          }
          showPanel();
          showBanner();
        });
      }

      window.resetCookieConsent = function () {
        deleteCookie(CONSENT_COOKIE_NAME);
        showBanner();
        hidePanel();
        if (analyticsToggle) analyticsToggle.checked = false;
      };
    })();

