                /*$main.css({
                    height: $(window).height() - ( $header.outerHeight() + $adminBar.outerHeight() )
                });*/
                jQuery('#main-footer').addClass('fixed-footer');
            } else {
                /*$main.css({
                    height: ""
                });*/
            }
        }
    }

    $(document).ready(function() {

