function manageTopicsSlider() {
  const $slider = $('.slick-topics-slider');
  const isInited = $slider.hasClass('slick-initialized');
  const isDesktop = window.matchMedia('(min-width: 768px)').matches;

  if (isDesktop && !isInited) {
    $slider.slick({
      slidesToShow: 5,
      slidesToScroll: 3,
      dots: true,
      arrows: true,
      customPaging: function () {
        return '<div class="custom-dot"></div>';
      },
      responsive: [
        { breakpoint: 1024, settings: { slidesToShow: 2 } }
      ]
    });
  } else if (!isDesktop && isInited) {
    $slider.slick('unslick');
  }
}

