            var newestGen = {};
            var keep = [];
            var i, key;

            for (i = 0; i < tracked.length; i++) {
                key = tracked[i].origin + '|' + tracked[i].type;
                if (!(key in newestGen) || tracked[i].gen > newestGen[key]) {
                    newestGen[key] = tracked[i].gen;
                }
            }

            for (i = 0; i < tracked.length; i++) {
                var t = tracked[i];

                if (t.gen === 0) {
                    keep.push(t);
                    continue;
                }

                if (t.gen <= generation - 2 && newestGen[t.origin + '|' + t.type] > t.gen) {
                    try { nativeRemove.call(t.target, t.type, t.fn, t.opts); } catch (e) {}
