	/**
	 * Search for Smart Path Disclaimer Function
	 * @author layth abdelqader
	 * @param {string} text - text to filter by
	 * @param {string} cname - class name of element
	 */
	function SmartPathDisclaimer(text, cname) {
		// set up replacement fn
		var doReplacement = function(interval) {
			// clear interval
			clearInterval(interval);
			// lets start the loop and find all classnames/text that match
			const container = [...document.querySelectorAll(cname)];
			for (let i = 0; i < container.length; i++) {
				var classListing = [...container[i].classList];
				if (container[i].textContent.includes(text) && container[i].textContent.includes("transit"))
				{
					if(!container[i].textContent.includes(text + ':')){
						container[i].innerHTML = container[i].innerHTML.replace(text, "<strong>" + text + ':' + "</strong>");
					}
				} else if (container[i].textContent.includes(text) && container[i].textContent.includes("build phase")) {
					if(!container[i].textContent.includes(text + ':')){
						container[i].innerHTML = container[i].innerHTML.replace(text, "<strong>" + text + ':' + "</strong>");
					}
				} else if (container[i].textContent.includes(text)) {
					container[i].innerHTML = container[i].innerHTML.replace(text, "<strong>" + text + "</strong>");
				} else {
					container[i].classList.remove(
						"dv-sp-disclaimer-strong"
					);
				}
			}
		};
		// set up interval and wait for dgdatahub to load
		var interval = setInterval(function () {
			if (window.DGDataHub != undefined) {
									if (typeof window.DGDataHub.getWarningState !== "undefined" && window.DGDataHub.getWarningState().dgLoaded) {
						doReplacement(interval)
					}
							}
		}, 200);
	}

	/**
	 * Search highlighting is computed, transferred and parsed, then thrown away.
	 *
	 * The adapter defaults highlight_full_fields to the whole query_by list, so
	 * every response carries per-hit highlight blocks for all sixteen fields.
	 * Nothing reads them: no template in this file touches _highlightResult,
	 * and never has. Both highlight knobs are set to "none" below: the adapter
	 * injects highlight_full_fields on its own, which of the two wins is
	 * decided server-side, and naming both removes the doubt for free.
	 *
	 * Sized honestly before assuming it mattered: on the live i95 collection
	 * the highlight blocks are about 1% of a 428KB keystroke response, because
	 * the weight is the documents themselves - imageUrls is 48% of a 25KB hit
	 * and conditionalIncentives another 32%, and both are genuinely rendered,
	 * so neither can be excluded. This trim is kept because it is free and
	 * strictly correct - the server skips work nobody consumes - not because
	 * it moves the needle. Anyone tempted to chase response size further:
	 * measure the per-field split first, and note that the transfer was never
	 * what blocked the main thread - the re-render is.
	 *
	 * Gated on Theme Options -> Performance -> "Skip unused search highlighting"
	 * because a dealer's custom runtime JS (srp-js-function-render-runtime)
	 * could in principle read _highlightResult even though the theme does not.
	 * ?da-search-payload=full restores the old payload for one request, which
	 * is the way to test that theory on a live dealer before flipping the switch.
	 */
	var daTrimSearchPayload = true		&& new URLSearchParams(window.location.search).get('da-search-payload') !== 'full';

	/**
	 * Cancel a search the moment a newer one supersedes it.
	 *
	 * Michael's idea, confirmed by measurement on Slow 4G: typing "tundra" at
	 * a normal cadence put EIGHT multi_search requests in flight at once. The
	 * first two responses ate the whole link (444KB), "tun" through "tundra"
	 * all hit the client's 5s timeout, were retried, and timed out again - so
	 * the page settled with the box saying "tundra" and the results showing
	 * "tu". On a slow connection the stale downloads do not just waste
	 * transfer, they starve the one query the user actually wants and leave
	 * wrong results on screen.
	 *
	 * The adapter's client sends via axios/XHR, which complicates the obvious
	 * fix: a bare xhr.abort() fires the error path, axios rejects, and
	 * typesense-js treats that as a node failure and RETRIES - recreating the
	 * storm this exists to prevent. So a superseded request is silenced
	 * before it is aborted: every handler axios attached is stripped, then
	 * the native abort runs. Axios never learns; its promise simply never
	 * settles; the retry logic never fires. InstantSearch orders responses by
	 * query id, so the never-answered request was never going to render
	 * anyway.
	 *
	 * Fast connections are unaffected in practice: responses return in
	 * ~250ms and are done before the next keystroke, so there is rarely
	 * anything in flight to cancel.
	 */
	var daCancelStaleSearch = true		&& new URLSearchParams(window.location.search).get('da-cancel-stale-search') !== 'off';

	/**
	 * Arm content-visibility on the result cards (rule in algolia.css, gated
	 * on this class so the flag lives here with the other Performance flags).
	 * Off-screen cards then skip style recalculation and layout entirely on
	 * each render - the two largest named costs in the keystroke trace after
	 * the render itself. See the comment block in algolia.styl for numbers.
	 */
	if (true		&& new URLSearchParams(window.location.search).get('da-content-visibility') !== 'off') {
		document.documentElement.classList.add('da-cv');
	}

	// The header that marks a request as this SRP's own. Sent by the adapter's
	// client (below) and recognised by the canceller; nothing else uses it.
	var DA_SRP_SEARCH_HEADER = 'X-DA-SRP-Search';

	if (daCancelStaleSearch) {
		(function () {
			var inFlight = null;

			/**
			 * Ownership is carried by the request itself, not inferred.
			 *
			 * Keying on '/multi_search' alone claimed EVERY Typesense client on
			 * the page - the inventory-widget shortcode builds its own adapter,
			 * and one slot shared between it and the SRP meant each aborted the
			 * other's requests. A silenced request never settles its promise,
			 * so the loser hung forever: the widget spinning, or the SRP stuck
			 * in stalled with stale results.
			 *
			 * A timing-based claim (a ticket raised beside each search call)
			 * only narrowed that: our XHR opens several microtasks after the
			 * call, so a request already mid-chain in another adapter could
			 * drain the ticket first and invert ownership, and typesense-js
			 * schedules its retries on a timer, which left every retry
			 * unclaimable. Both go away if the request announces itself: the
			 * SRP's client sends DA_SRP_SEARCH_HEADER (see the adapter's server
			 * config), no other client on the page does, and a retry re-sends
			 * the same headers.
			 *
			 * The header costs no round trips. These requests already carry
			 * x-typesense-api-key and a JSON content type, so they are already
			 * preflighted; the endpoint was measured to reflect an arbitrary
			 * requested header back in access-control-allow-headers, with
			 * access-control-max-age 3600.
			 */
			var nativeSend   = XMLHttpRequest.prototype.send;
			var nativeAbort  = XMLHttpRequest.prototype.abort;
			var nativeAdd    = XMLHttpRequest.prototype.addEventListener;
			var nativeRem    = XMLHttpRequest.prototype.removeEventListener;
			var nativeHeader = XMLHttpRequest.prototype.setRequestHeader;

			XMLHttpRequest.prototype.setRequestHeader = function (name, value) {
				if (String(name).toLowerCase() === DA_SRP_SEARCH_HEADER.toLowerCase()) {
					this.__daSearch = true;
					this.__daHandlers = [];
				}
				return nativeHeader.apply(this, arguments);
			};

			// Record what axios attaches to a search request, so it can all be
			// detached at supersede time. Non-search requests skip the
			// bookkeeping entirely.
			XMLHttpRequest.prototype.addEventListener = function (type, fn, opts) {
				if (this.__daSearch && this.__daHandlers) {
					this.__daHandlers.push([type, fn, opts]);
				}
				return nativeAdd.apply(this, arguments);
			};

			function silence(xhr) {
				(xhr.__daHandlers || []).forEach(function (h) {
					try { nativeRem.call(xhr, h[0], h[1], h[2]); } catch (e) {}
				});
				xhr.__daHandlers = null;
				// Older axios wires the on* properties instead of listeners.
				xhr.onreadystatechange = xhr.onload = xhr.onerror = null;
				xhr.onabort = xhr.ontimeout = xhr.onloadend = xhr.onprogress = null;
				try { nativeAbort.call(xhr); } catch (e) {}
			}

			XMLHttpRequest.prototype.send = function () {
				if (this.__daSearch) {
					if (inFlight && inFlight !== this) {
						silence(inFlight);
					}
					inFlight = this;

					var self = this;
					// Attached via the native path so silence() cannot strip it.
					nativeAdd.call(this, 'loadend', function () {
						if (inFlight === self) { inFlight = null; }
					});
				}
				return nativeSend.apply(this, arguments);
			};
		})();
	}

