	/**
	 * Feeds spell one cab or bed several ways ("Double cab"/"Double Cab", "5-ft bed"/"5' Bed").
	 * Responses list each spelling group once with the summed count, and refining that entry
	 * filters on every spelling seen so far (GLOBAL-57526).
	 */
	(function () {
		var groups = { cab: {}, bed: {} };

		// OEM names written the brand's way; matching stays case-insensitive, so links keep working.
		var brandSpellings = { crewmax: 'CrewMax', xtracab: 'XtraCab', supercrew: 'SuperCrew', supercab: 'SuperCab' };

		function capitalize(text) {
			return text
				.replace(/(^|\s)(\S)/g, function (m, space, letter) { return space + letter.toUpperCase(); })
				.replace(/\b[a-z]+\b/gi, function (word) { return brandSpellings[word.toLowerCase()] || word; });
		}

		function capitals(text) {
			return (text.match(/[A-Z]/g) || []).length;
		}

		// Beds group by length in feet ("5.5-Ft.", "5.5' Bed", "5'6\""); anything else by its text, any case.
		function canonical(attribute, raw) {
			var text = String(raw).trim().replace(/\s+/g, ' ');
			if (attribute === 'bed') {
