			 * expensive observer on this page.
			 *
			 * Two problems it had:
			 *
			 *  1. It observed style attributes across the slider's whole subtree and
			 *     then wrote styles to the tooltips *inside* that subtree, so every
			 *     run scheduled another run. It only ever settled because the values
			 *     converged.
			 *  2. It read offsetWidth and then wrote, synchronously, on every single
			 *     mutation - a forced layout each time. Typing in the SRP search box
			 *     re-renders the results and fires this constantly.
			 *
			 * So: coalesce to one run per frame, and disconnect around our own writes
			 * so they cannot feed back in. Skipping unchanged values keeps us from
			 * dirtying style for no reason.
			 */
			const OBSERVE_OPTIONS = {
				childList: true,
				subtree: true,
				attributes: true,
				attributeFilter: ['style']
			};

			const setStyle = (el, prop, value) => {
				if (el.style[prop] !== value) {
					el.style[prop] = value;
				}
			};

			const applyTooltipPositions = () => {
				const handles = priceSlider.querySelectorAll('.rheostat-handle');

				if (handles.length !== 2) {
					return;
				}

				const tooltip1 = handles[0].querySelector('.rheostat-tooltip');
				const tooltip2 = handles[1].querySelector('.rheostat-tooltip');
				const background = priceSlider.querySelector('.rheostat-background');

				if (!tooltip1 || !tooltip2 || !background) {
					return;
				}

				// every read first, then every write - one layout pass, not two
				const handle1Left = parseFloat(handles[0].style.left) || 0;
				const handle2Left = parseFloat(handles[1].style.left) || 100;
				const sliderWidth = background.offsetWidth;

				const handle1Offset = (handle1Left / 100) * sliderWidth;
				const handle2Offset = (handle2Left / 100) * sliderWidth;

				setStyle(tooltip1, 'left', `-${handle1Offset}px`);
				setStyle(tooltip1, 'transform', 'none');

