	// Per-frame scroll to top: iOS WebKit cancels native smooth scrolling while the
	// toolbar settles after an overscroll bounce, leaving shoppers at the bottom.
	let daSrpScrollAnimationId = 0;

	const daSrpScrollToTop = () => {
		const animationId = ++daSrpScrollAnimationId;
		const startY = window.scrollY;
		const duration = 400;
		let startTime = null;

		if (startY <= 0) {
			return;
		}

		const cancel = () => {
			daSrpScrollAnimationId++;
		};

		window.addEventListener('touchstart', cancel, { once: true, passive: true });

		const step = now => {
			if (animationId !== daSrpScrollAnimationId) {
				return;
			}
			if (startTime === null) {
				startTime = now;
			}

			const progress = Math.min((now - startTime) / duration, 1);
			const eased = 1 - Math.pow(1 - progress, 3);
			window.scrollTo(0, Math.round(startY * (1 - eased)));

			if (progress < 1) {
				requestAnimationFrame(step);
				return;
			}

			window.removeEventListener('touchstart', cancel);
			if (window.scrollY > 0) {
				requestAnimationFrame(() => window.scrollTo(0, 0));
			}
		};

		requestAnimationFrame(step);
	};

