        // event measures the delta from wherever that event already landed, which
        // is zero for anything but a slow drag.
        var scrollAnchor = null;

        /**
         * Only a scroll the user actually drove should dismiss the keyboard.
         *
         * The first version of this compared scroll distance alone, which broke
         * tapping the field on iOS whenever the page was scrolled even slightly.
         * Focusing an input on iOS makes the BROWSER scroll: the keyboard shrinks
         * the visual viewport, and a collapsed address bar expands. Both move
         * window.scrollY well past this threshold within a frame or two of focus,
         * so the handler blurred the field the moment it was tapped. It worked at
         * the very top of the page only because there was nothing to adjust.
         *
         * A drag produces touchmove. Browser-driven scroll does not, so requiring
         * a recent touchmove separates the two. Anything else re-anchors instead
         * of dismissing, which also covers the keyboard opening mid-session.
         */
        var lastTouchMove = 0;

        document.addEventListener('touchmove', function () {
            lastTouchMove = Date.now();
        }, { passive: true });

