 * previous refinement state.
 *
 * @returns {{status: string, minPrice: number|null, maxPrice: number|null, year: string, mileage: string, make: string, model: string, color: string, trim: string, bodyStyle: string, features: string, drivetrain: string}}
 */
function buildSdFilterSearchPayload() {
	var helperState = search.helper && search.helper.state ? search.helper.state : {};
	var status = "All";
	var certificationRefinements = getSdStateFilterValues(helperState, ["flags.type"]);

	if (certificationRefinements !== "All") {
		var selectedCount = certificationRefinements.split("|").length;
		var totalCount = 0;

		if (search.helper && search.helper.lastResults) {
			var facetValues = search.helper.lastResults.getFacetValues("flags.type");
			if (Array.isArray(facetValues)) {
				totalCount = facetValues.length;
			}
		}

		if (totalCount > 0 && selectedCount >= totalCount) {
			status = "Mixed";
		} else {
			status = "CPO";
		}
	} else if (srpCondition) {
		status = srpCondition;
	}

	/**
	 * Handle price, year, and mileage as special cases since they can be either a range facet refinement or a numeric slider refinement depending on how the user has interacted with the filters.
	 */
	var priceBounds = getSdPriceBounds(helperState);
	var year = getSdYearValue(helperState);

	var mileageRangeSelection = getSdStateFilterValues(helperState, ["mileageRange"]);
	var mileage = mileageRangeSelection !== "All" ? mileageRangeSelection : getSdNumericRangeValue(helperState, "mileage", function(v) { return Number(v).toLocaleString(); });

	return {
		status: status,
		minPrice: priceBounds.min,
		maxPrice: priceBounds.max,
		year: year,
		mileage: mileage,
		make: getSdStateFilterValues(helperState, ["make"]),
		model: getSdStateFilterValues(helperState, ["model"]),
		color: getSdStateFilterValues(helperState, ["genericColor", "generic_color"]),
		trim: getSdStateFilterValues(helperState, ["trim"]),
		bodyStyle: getSdStateFilterValues(helperState, ["body"]),
		features: getSdStateFilterValues(helperState, ["features"]),
		drivetrain: getSdStateFilterValues(helperState, ["drivetrain"])
	};
}

/**
 * Creates a stable signature for the current search helper state so we can
 * detect real SRP refinement changes across renders.
 *
 * This is used only as change detection. The actual Shift Digital payload is
 * still built separately from the supported helper refinements.
 *
 * @returns {string}
 */
function buildSdSearchStateSignature() {
	if (!search.helper || !search.helper.state) {
		return JSON.stringify({
			query: "",
			disjunctiveFacetsRefinements: {},
			facetsRefinements: {},
			hierarchicalFacetsRefinements: {},
			numericRefinements: {}
		});
	}

	return JSON.stringify({
		query: search.helper.state.query || "",
		disjunctiveFacetsRefinements: search.helper.state.disjunctiveFacetsRefinements || {},
		facetsRefinements: search.helper.state.facetsRefinements || {},
		hierarchicalFacetsRefinements: search.helper.state.hierarchicalFacetsRefinements || {},
		numericRefinements: search.helper.state.numericRefinements || {}
	});
}

/**
 * Builds a signature of only the facet/numeric refinement state (excludes
 * the search query) so facet-only changes can be distinguished from
 * query-only changes.
 *
 * @returns {string}
 */
function buildSdFacetStateSignature() {
	if (!search.helper || !search.helper.state) {
		return JSON.stringify({
			disjunctiveFacetsRefinements: {},
			facetsRefinements: {},
			hierarchicalFacetsRefinements: {},
			numericRefinements: {}
		});
	}

	return JSON.stringify({
		disjunctiveFacetsRefinements: search.helper.state.disjunctiveFacetsRefinements || {},
		facetsRefinements: search.helper.state.facetsRefinements || {},
		hierarchicalFacetsRefinements: search.helper.state.hierarchicalFacetsRefinements || {},
		numericRefinements: search.helper.state.numericRefinements || {}
	});
}

