}

/**
 * Sends the pageview and filterSearch owed to a query-only search.
 *
 * Called straight after typedSearch so Shift Digital sees
 * typedSearch -> pageview -> filterSearch, and off a timer when the query
 * changed without anything being typed.
 *
 * @returns {void}
 */
function flushSdQueryAnalytics() {
	clearTimeout(sdQueryAnalyticsTimer);
	sdQueryAnalyticsTimer = null;

	if (!sdQueryAnalyticsPending) {
		return;
	}

	sdQueryAnalyticsPending = false;
	sendSdSrpPageViewAndFilterSearch();
}

/**
 * Watches InstantSearch render cycles and dispatches Shift Digital analytics
 * only when the underlying helper state has actually changed.
 *
 * The helper state signature prevents duplicate sends on unrelated renders
 * while still allowing select and deselect facet actions to be tracked.
 *
 * Facet changes send immediately. Query changes defer to flushSdQueryAnalytics
 * so typedSearch keeps its place at the front of the sequence.
 *
 * @returns {void}
 */
function handleSdSrpRenderAnalytics() {
	if (!(haveSdAnalytics && typeof(sd) !== "undefined")) {
		return;
	}

	if (!search.helper || !search.helper.lastResults) {
		return;
	}

	var nextSdSearchStateSignature = buildSdSearchStateSignature();
	var nextSdFacetStateSignature = buildSdFacetStateSignature();
	var nextSdQuery = search.helper.state.query || "";

	if (lastSdSearchStateSignature === null) {
		lastSdSearchStateSignature = nextSdSearchStateSignature;
		lastSdFacetStateSignature = nextSdFacetStateSignature;
		lastSdQuery = nextSdQuery;
		return;
	}

	var facetsChanged = nextSdFacetStateSignature !== lastSdFacetStateSignature;
	var queryChanged = nextSdQuery !== lastSdQuery;
	lastSdSearchStateSignature = nextSdSearchStateSignature;
	lastSdFacetStateSignature = nextSdFacetStateSignature;
	lastSdQuery = nextSdQuery;

	if (facetsChanged) {
		// The facet send carries the current query too, so one send covers both.
		sdQueryAnalyticsPending = false;
		clearTimeout(sdQueryAnalyticsTimer);
		sdQueryAnalyticsTimer = null;

		var deferAnalyticsUpdate = window.requestIdleCallback || function(callback) {
			setTimeout(callback, 0);
		};

		deferAnalyticsUpdate(function () {
			sendSdSrpPageViewAndFilterSearch();
		});

		return;
	}

	if (queryChanged) {
		sdQueryAnalyticsPending = true;
		clearTimeout(sdQueryAnalyticsTimer);
		sdQueryAnalyticsTimer = setTimeout(flushSdQueryAnalytics, 1200);
	}
}

