(function () {
                var modal = document.querySelector('[data-kia-window-sticker-modal]');
                var frame = document.querySelector('[data-kia-window-sticker-frame]');
                var activeTrigger = null;

                if (!modal || !frame) {
                    return;
                }

                function open(url, trigger) {
                    activeTrigger = trigger || null;
                    frame.setAttribute('src', url);
                    modal.classList.add('is-open');
                    modal.setAttribute('aria-hidden', 'false');
                    document.body.classList.add('ag-kia-window-sticker-modal-open');
                }

                function close() {
                    modal.classList.remove('is-open');
                    modal.setAttribute('aria-hidden', 'true');
                    frame.removeAttribute('src');
                    document.body.classList.remove('ag-kia-window-sticker-modal-open');

                    if (activeTrigger && typeof activeTrigger.focus === 'function') {
                        activeTrigger.focus();
                    }
                }

                function closest(element, selector) {
                    while (element && element !== document) {
                        if (element.matches && element.matches(selector)) {
                            return element;
                        }

                        element = element.parentNode;
                    }

                    return null;
                }

                window.AutoGoKiaWindowSticker = {
                    open: open,
                    close: close
                };

                document.addEventListener('click', function (event) {
                    var link = closest(event.target, '[data-kia-window-sticker-link]');

                    if (!link) {
                        link = closest(event.target, 'a[href*="/kia-window-sticker/"]');
                    }

                    if (link) {
                        // stopPropagation, not stopImmediatePropagation: the page's handlers still
                        // never see the click, but the Event Manager's listener on document does.
                        event.preventDefault();
                        event.stopPropagation();
                        open(link.href, link);
                    }
                }, true);

                document.addEventListener('click', function (event) {
                    if (!closest(event.target, '[data-kia-window-sticker-close]')) {
                        return;
                    }

                    event.preventDefault();
                    close();
                });

                document.addEventListener('keyup', function (event) {
                    if ((event.key === 'Escape' || event.keyCode === 27) && modal.classList.contains('is-open')) {
                        close();
                    }
                });
            })();

