    // The ?da-slide-cap=N override, read once per page instead of once per
    // trim call - it cannot change while the page lives.
    var daSlideCapOverride = parseInt(new URLSearchParams(window.location.search).get('da-slide-cap'), 10);

    function _limitSlidesPerVehicleCard(scope) {
        // With a scope, trim just that carousel; without one, sweep the page.
        let vehicleCardCarousels = scope ? [scope] : document.querySelectorAll('.srp-swiper-vehicles');

        let srpMaxImageLength = 5;
        if (daSlideCapOverride > 0) {
            srpMaxImageLength = daSlideCapOverride;
        }

        vehicleCardCarousels.forEach(slider => {

            let swiperWrapper = slider.querySelector('.swiper-wrapper');
            let swiperSlides = swiperWrapper.querySelectorAll('.swiper-slide');

            if (swiperSlides.length > srpMaxImageLength && ! swiperWrapper.dataset.maximages) {

