	/**
     * Transform the incentives data to be more easily accessible in the template
     *
     * @private
     */
	function transformIncentives(item) {

        if (!showConditionalIncentives || !item.conditionalIncentives) return item;

		const formatDate = (dateString) => {
			if (!dateString) return null;
			const date = new Date(dateString);
			const month = (date.getMonth() + 1).toString().padStart(2, '0');
			const day = date.getDate().toString().padStart(2, '0');
			const year = date.getFullYear();
			return `${month}-${day}-${year}`;
		};

		const mapNexusIncentive = inc => {
			if (!inc.value || inc.value === 0) return null;

			const incentive = {};
			if (inc.title) incentive.programDescription = inc.title;
			if (inc.title) incentive.programName = inc.title;
			if (inc.value) incentive.programValue = inc.value;
			if (inc.disclaimer) incentive.disclaimerText = inc.disclaimer;
			if (inc.effectiveDate) incentive.effectiveDate = formatDate(inc.effectiveDate);
    		if (inc.expiryDate) incentive.expiryDate = formatDate(inc.expiryDate);
			if (inc.description) {
			incentive.programRuleList = [{
				description: inc.description
			}];
			}
			return incentive;
		};

		if (isNexusToyota || isNexusAcura || isNexusHonda || isNexusEnabled) {
			item.conditionalIncentives = Array.isArray(item.conditionalIncentives)
			? item.conditionalIncentives
				.map(mapNexusIncentive)
				.filter(incentive => incentive !== null && Object.keys(incentive).length > 0)
			: [];

			item.incentives = Array.isArray(item.incentives)
				? item.incentives
					.map(mapNexusIncentive)
					.filter(incentive => incentive !== null && Object.keys(incentive).length > 0)
				: [];
		}


		let priorityIncentives = item.conditionalIncentives.filter(incentive => {
			const desc = (incentive.programDescription || '').toString().toLowerCase();
			return desc.includes('military') || desc.includes('college') ||
				desc.includes('graduate') || desc.includes('first responder');
		});

		let otherIncentives = item.conditionalIncentives.filter(incentive => {
			const desc = (incentive.programDescription || '').toString().toLowerCase();
			return !desc.includes('military') && !desc.includes('college') &&
				!desc.includes('graduate') && !desc.includes('first responder');
		});

		if (priorityIncentives.length === 0)
		{
			priorityIncentives = item.conditionalIncentives.slice(0, 3);
			otherIncentives = otherIncentives.slice(3, otherIncentives.length);
		}

		const regularIncentives = item.incentives || [];

		const remainingIncentivesCount = otherIncentives.length + regularIncentives.length;

		item._transformed = {
			priorityIncentives,
			otherIncentives,
			incentives: item.incentives || [],
			hasAdditionalIncentives: otherIncentives.length > 0,
			remainingIncentivesCount
		};

		return item;
	}

    /**
     * Live Swiper instances and the observer that lazily creates them, kept so
     * the NEXT render can tear them down.
     *
     * Swiper attaches its drag-tracking listeners (touchmove, pointermove,
     * touchend and friends) to document, per instance - it has to, to keep
     * tracking a drag that leaves the container. InstantSearch replaces the
     * whole results list on every render, so the containers those instances
     * were built on are discarded, but the instances themselves - and their
     * document-level listeners - were never destroyed. Measured on the live
     * i95 SRP: ~220 document/window listeners added per six-character search
     * by swiper-bundle alone, none ever removed, 1,873 net after six searches.
     * Every tap on the page then runs the whole accumulated chain, which is
     * the path WebKit dispatches slowest.
     *
     * Same shape for the IntersectionObserver: a fresh one per render,
     * observing the new cards, with the old one left alive holding the old
     * ones. destroy() + disconnect() at the top of the rebuild is the whole
     * fix. Not behind a Theme Options switch for the same reason the delegated
     * click handlers were not: removing a leak has no behaviour to opt out of.
     */
    var daSwipers = [];
    var daSwiperObserver = null;

    /**
     * Builds the SRP vehicle image carousel on the vehicle card
     *
     * @private
     */
    function _buildSRPImageCarousel() {
        // Tear down the previous render's carousels before building this one.
        // cleanStyles stays false: the old containers are already detached,
        // so restyling them is wasted work.
        daSwipers.forEach(function (s) {
            try { s.destroy(true, false); } catch (e) { /* already dead is fine */ }
        });
        daSwipers.length = 0;

        if (daSwiperObserver) {
            daSwiperObserver.disconnect();
        }

        // Trim excess slides from EVERY card now, not on first intersection -
        // see the note on _limitSlidesPerVehicleCard. The in-intersect call
        // below stays as a belt for slides added late by anything else.
        _limitSlidesPerVehicleCard();

        /**
         * b/o: Allow the loading of Swipers when needed and scrolled into view
         * using the javascript intersection Observer API
         */
        const observerOptions = {
            root: null,
            rootMargin: '0px',
            threshold: 0.2 // when 20% of the element is in view proceed with loading the swiper
        };

        function handleIntersect(entries, observer) {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    // Belt for slides added late by anything else, scoped to
                    // the one carousel entering view - the unscoped call here
                    // re-walked every wrapper on the page per intersecting
                    // card, ~576 wrapper scans across one scrolled 24-card
                    // page, all duplicating the render-time trim above.
                    _limitSlidesPerVehicleCard(entry.target);
                    _maybeRemoveSwiperNavigation(entry.target)
                    // Initialize Swiper for this container
                     daSwipers.push(new Swiper(entry.target, {
                        loop: true,
                        /**
                         * Swiper's default touchAngle is 45 degrees, meaning it claims
                         * any drag within 45 degrees of horizontal as a carousel swipe.
                         * A thumb flick is rarely perfectly vertical, so on a phone -
                         * where these cards fill most of the screen - a large share of
                         * scroll attempts get swallowed by the carousel and the page
                         * does not move. That reads exactly as "scrolling is stuck".
                         *
                         * 25 degrees keeps deliberate horizontal swipes working while
                         * letting anything steeper scroll the page.
                         */
                        touchAngle: 25,
                        navigation: {
                            nextEl: `.swiper-button-next`,
                            prevEl: `.swiper-button-prev`
                        }
                    }));

                    observer.unobserve(entry.target);
                }
            });
        }

        daSwiperObserver = new IntersectionObserver(handleIntersect, observerOptions);
        // Get all of the swipers on the page
        let vehicleCardCarousels = document.querySelectorAll('.srp-swiper-vehicles');

        vehicleCardCarousels.forEach(slider => {
            daSwiperObserver.observe(slider);
        });
    }

    /* b/o: Image Aspect Ratio Fix */

    /**
     * Calculate a new height based on previous values as well as a new width
     *
     * @param newWidth the new width of the element to calulcate the height
     * @param originalWidth the original width of the item to find aspect ratio
     * @param originalHeight the original height of the item to find aspect ratio
     * @returns number
     */
    function calculateHeight(newWidth, originalWidth, originalHeight) {
        const aspectRatio = originalWidth / originalHeight;
        const newHeight = newWidth / aspectRatio;
        return parseFloat(newHeight.toFixed(1));
    }

    /*
     * e/o: Image Aspect Ratio Fix
     *
     * _debounce/_onResize/_constrainImageAspectRatio were removed here. The
     * resize handler measured every card with jQuery .width() and then did
     * nothing with the result - the two lines that used it had been commented
     * out - so all it did was force a synchronous layout per vehicle card on
     * every render. It was also called from onRenderHandler, and each call
     * added another window resize listener that was never removed.
     *
     * It was the single largest remaining cost on this page: 2,863ms of forced
     * reflow attributed to jQuery's dimension getter while typing one search.
     *
     * Note: shortcodes/inventory-widget/sc.inventory-widget.php still carries a
     * copy of the same dead pattern.
     */

	/**
	 * Render is deliberately split in two.
	 *
	 * instantsearch re-renders roughly 1.7 times per keystroke - measured at ten
	 * renders for six typed characters on the used-vehicles SRP. The tail of this
	 * handler re-initialises against the freshly built card DOM: Swiper carousels,
	 * lazy-image observers, SmartPath, and the forms. None of that is incremental
	 * state - every one rebuilds from the current result set - so running them on
	 * an intermediate render produces work the next keystroke immediately throws
	 * away.
	 *
	 * onRenderImmediate() is everything that keeps what is on screen truthful:
	 * result counts, facet container visibility, filter tags. Delaying any of it
	 * would leave stale numbers on screen while the user types.
	 *
	 * onRenderSettled() is everything that re-initialises, trailing-debounced so
	 * it runs once when typing stops. 250ms rather than the 100ms used for the
	 * search debounce above, because this work is an order of magnitude heavier
	 * and none of it is visible state.
	 *
	 * Gated on Theme Options -> Performance -> "Defer post-render work on the SRP",
	 * on by default, with the settle delay configurable there too.
	 * ?da-render-split=off still runs both halves inline for this request only, so
	 * support can rule it in or out on a live page without changing the setting.
	 */
	// Floor 100, matching the spinner: its old min of 0 made daTypingActive()
	// always false, which switched render-on-settle off while its switch still
	// read on. Below about 100ms neither feature does anything useful anyway.
	var DA_SETTLE_MS = 250;
	var daSettleTimer = null;
	var daRenderSplit = true		&& new URLSearchParams(window.location.search).get('da-render-split') !== 'off';

	function onRenderHandler()
	{
		/**
		 * Cleared before the mid-burst return on purpose: a timer armed by
		 * the last pre-burst render would otherwise fire DURING the typing
		 * window the gate below exists to protect - full Swiper rebuild,
		 * slide trims, a burned reaper generation, all for a render that
		 * never happened. The settled render that follows the held response
		 * re-arms it, so nothing is lost by clearing here.
		 */
		clearTimeout(daSettleTimer);

		/**
		 * Mid-burst, this render can only be loading-state churn: responses
		 * are being held by the render-on-settle gate, so nothing on screen
		 * has changed and both halves would run for nothing - measured at
		 * ~4.7s of main-thread time across one fast-typed word on the
		 * 4x-throttled bench, all of it between keystrokes the user was
		 * still typing. The render that matters fires when the held response
		 * delivers at settle, and typing is quiet by definition then, so
		 * this guard is never true for it.
		 */
		if (daRenderOnSettle && daTypingActive())
		{
			return;
		}

		onRenderImmediate();

		if (!daRenderSplit)
		{
			onRenderSettled();
			return;
