// Numbers and bed lengths in order (2 < 10, 5'7" < 5'10" < 6' < 6'6").
function daFacetByMeasure(a, b) {
	if (daFacetShowMore && a.isRefined !== b.isRefined) {
		return a.isRefined ? -1 : 1;
	}
	var measure = function (name) {
		var m = /^(\d+(?:\.\d+)?)'?\s*(?:(\d+(?:\.\d+)?)")?/.exec(name);
		return m ? parseFloat(m[1]) + (m[2] ? parseFloat(m[2]) / 12 : 0) : Infinity;
	};
	// Infinity - Infinity is NaN, so values with no measure fall through to their names, last.
	return (measure(a.name) - measure(b.name)) || a.name.localeCompare(b.name);
}

