 * One multi-search for every probe, on its own client without the search header: through
 * searchClient, the stale-search canceller and the sequence guard leave all but the last of
 * parallel probes pending forever, and with the header a probe could cancel a real search.
 * Resolves to {facet: true|false}, {} on a failure, or null after a 6s stall, so start always runs.
 */
function daProbeFacets(facets) {
	if (!facets.length) {
		return Promise.resolve({});
	}
	// The raw client takes the collection as-is; the adapter strips a /sort/ suffix the same way.
	var collection = indexName.split('/sort/')[0];
	var request = Promise.resolve().then(function () {
		var client = new TypesenseInstantSearchAdapter({
			server: Object.assign({}, typesenseAdapter.configuration.server, {additionalHeaders: {}}),
			additionalSearchParameters: {query_by: 'make'}
		}).typesenseClient;

		return client.multiSearch.perform({
			searches: facets.map(function (facet) { return {collection: collection, q: '*', per_page: 0, facet_by: facet}; })
		}, {query_by: 'make'});
	}).then(function (res) {
		return facets.reduce(function (found, facet, i) {
			found[facet] = !!(res.results[i] && !res.results[i].error);
			return found;
		}, {});
	});
	var stall = new Promise(function (resolve) { setTimeout(function () { resolve(null); }, 6000); });

	return Promise.race([request, stall]).catch(function () { return {}; });
}

