/**
 * Mobile keyboard affordances for the search box.
 *
 * InstantSearch renders the field itself, so these are applied after start().
 * Two problems on a phone: the Return key had no clear meaning, and once the
 * keyboard was up there was no obvious way down - the field sits near the top
 * of the page with no surrounding tappable dead space.
 *
 *  - enterkeyhint labels the Return key "Search" on iOS and Android.
 *  - Submitting blurs, so Return actually closes the keyboard. InstantSearch
 *    already suppresses the form's default submit, so nothing navigates.
 *  - Scrolling the results blurs too. This is the usual mobile search pattern:
 *    once you scroll, you are reading results rather than typing. Gated on a
 *    real scroll distance so a stray pixel of movement does not dismiss it,
 *    and on touch input so desktop is unaffected.
 */
function daSetupSearchBoxKeyboard() {
    var searchInput = document.querySelector('#searchbox .ais-SearchBox-input');

    // Depending on the branch above, start() happens inside a promise, so the
    // field may not exist yet. Bound off 'render' and guarded, rather than run
    // inline - an earlier inline version silently did nothing for exactly this
    // reason, and looked like it worked because InstantSearch blurs on submit
    // by itself.
    if (!searchInput || searchInput.dataset.daKeyboardReady) {
        return;
    }

    searchInput.dataset.daKeyboardReady = '1';
    searchInput.setAttribute('enterkeyhint', 'search');

    if (window.matchMedia('(hover: none)').matches) {
        // Anchor on focus, not on the first scroll event. Anchoring on the first
        // event measures the delta from wherever that event already landed, which
        // is zero for anything but a slow drag.
        var scrollAnchor = null;

        /**
         * Only a scroll the user actually drove should dismiss the keyboard.
         *
         * The first version of this compared scroll distance alone, which broke
         * tapping the field on iOS whenever the page was scrolled even slightly.
         * Focusing an input on iOS makes the BROWSER scroll: the keyboard shrinks
         * the visual viewport, and a collapsed address bar expands. Both move
         * window.scrollY well past this threshold within a frame or two of focus,
         * so the handler blurred the field the moment it was tapped. It worked at
         * the very top of the page only because there was nothing to adjust.
         *
         * A drag produces touchmove. Browser-driven scroll does not, so requiring
         * a recent touchmove separates the two. Anything else re-anchors instead
         * of dismissing, which also covers the keyboard opening mid-session.
         */
        var lastTouchMove = 0;

        document.addEventListener('touchmove', function () {
            lastTouchMove = Date.now();
        }, { passive: true });

        searchInput.addEventListener('focus', function () {
            scrollAnchor = window.scrollY;
        });

        searchInput.addEventListener('blur', function () {
            scrollAnchor = null;
        });

        // Keyboard show/hide relays out the page. Re-anchor rather than reading it
        // as the shopper scrolling away from the field.
        if (window.visualViewport) {
            window.visualViewport.addEventListener('resize', function () {
                if (scrollAnchor !== null) {
                    scrollAnchor = window.scrollY;
                }
            });
        }

        window.addEventListener('scroll', function () {
            if (scrollAnchor === null || document.activeElement !== searchInput) {
                return;
            }

            if (Date.now() - lastTouchMove > 500) {
                scrollAnchor = window.scrollY;
                return;
            }

            if (Math.abs(window.scrollY - scrollAnchor) > 40) {
                searchInput.blur();
            }
        }, { passive: true });
    }
}

