				return values.join("|");
			}
		}
	}

	return "All";
}

/**
 * Reads a numeric range slider value from the InstantSearch helper state,
 * falling back to the facet stats (full inventory bounds) when the user
 * has not moved the slider.
 *
 * @param {object} helperState  search.helper.state
 * @param {string} attribute    The Algolia attribute name (e.g. 'rangeSliderPrice', 'yr')
 * @param {function|null} formatter  Optional formatter for min/max values
 * @returns {string}
 */
function getSdNumericRangeValue(helperState, attribute, formatter) {
	var refinements = (helperState.numericRefinements || {})[attribute] || {};
	var stats = {};

	if (search.helper && search.helper.lastResults && search.helper.lastResults.disjunctiveFacets) {
		var facet = search.helper.lastResults.disjunctiveFacets.find(function(f) { return f.name === attribute; });
		if (facet && facet.stats) {
			stats = facet.stats;
		}
	}

	var min = refinements[">="] ? refinements[">="][0] : (stats.min != null ? stats.min : null);
	var max = refinements["<="] ? refinements["<="][0] : (stats.max != null ? stats.max : null);

	if (min === null && max === null) {
		return "All";
	}

	if (formatter) {
		return formatter(min) + " - " + formatter(max);
	}

	return min + " - " + max;
}

/**
 * Returns the year for the Shift Digital filterSearch payload.
 *
 * Shift Digital wants a single year only when the shopper has actually narrowed
 * to one. Every "more than one year is showing" case reports "All" - including a
 * year slider spanning a range, which previously reported a shared "2015 - 2026"
 * string that read as two values in one prop.
 *
 * @param {object} helperState  search.helper.state
 * @returns {string}
 */
function getSdYearValue(helperState) {
	var yearFacetSelection = getSdStateFilterValues(helperState, ["year", "yr"]);

	if (yearFacetSelection !== "All") {
		return yearFacetSelection.indexOf("|") === -1 ? yearFacetSelection : "All";
	}

	// Only a slider collapsed onto one year counts as picking a year.
	var sliderRefinements = (helperState.numericRefinements || {})["yr"] || {};
	var min = sliderRefinements[">="] ? sliderRefinements[">="][0] : null;
	var max = sliderRefinements["<="] ? sliderRefinements["<="][0] : null;

	if (min !== null && max !== null && Number(min) === Number(max)) {
		return String(Math.round(min));
	}

	return "All";
}

/**
 * Returns the min and max price as plain integers for the Shift Digital
 * filterSearch payload. Checks finalPriceRange bucket selections first,
 * then falls back to the rangeSliderPrice numeric refinements, then to
 * the full facet stats (inventory bounds) when no filter is active.
 *
 * @returns {{min: number|null, max: number|null}}
 */
function getSdPriceBounds(helperState) {
	var refinementSources = [
		helperState.disjunctiveFacetsRefinements || {},
		helperState.facetsRefinements || {}
	];

	for (var i = 0; i < refinementSources.length; i++) {
		var buckets = refinementSources[i]["finalPriceRange"];
		if (buckets && buckets.length > 0) {
			var vals = Array.isArray(buckets) ? buckets : [buckets];
			var mins = [];
			var maxes = [];

			vals.forEach(function(bucket) {
				var s = bucket.replace(/[$,]/g, '');
				var below = s.match(/^(\d+)\s+and\s+Below$/i);
				var above = s.match(/^(\d+)\s+and\s+Up$/i);
				var range = s.match(/^(\d+)\s+-\s+(\d+)$/);

				if (below)      { mins.push(0);                    maxes.push(parseInt(below[1], 10)); }
				else if (above) { mins.push(parseInt(above[1], 10)); }
				else if (range) { mins.push(parseInt(range[1], 10)); maxes.push(parseInt(range[2], 10)); }
			});

			if (mins.length > 0 || maxes.length > 0) {
				return {
					min: mins.length > 0 ? Math.min.apply(null, mins) : null,
					max: maxes.length > 0 ? Math.max.apply(null, maxes) : null
				};
			}
		}
	}

	var sliderRefinements = (helperState.numericRefinements || {})["rangeSliderPrice"] || {};
	var stats = {};

	if (search.helper && search.helper.lastResults && search.helper.lastResults.disjunctiveFacets) {
		var priceFacet = search.helper.lastResults.disjunctiveFacets.find(function(f) {
			return f.name === "rangeSliderPrice";
		});
		if (priceFacet && priceFacet.stats) {
			stats = priceFacet.stats;
		}
	}

	var min = sliderRefinements[">="] ? sliderRefinements[">="][0] : (stats.min != null ? stats.min : null);
	var max = sliderRefinements["<="] ? sliderRefinements["<="][0] : (stats.max != null ? stats.max : null);

	return {
		min: min !== null ? Math.round(min) : null,
		max: max !== null ? Math.round(max) : null
	};
}

/**
 * Builds the Shift Digital filterSearch payload from the current InstantSearch
 * helper state.
 *
 * This keeps supported facet values in sync with the interaction that triggered
 * the render instead of relying on URL parameters that may still reflect the
 * previous refinement state.
 *
 * @returns {{status: string, minPrice: number|null, maxPrice: number|null, year: string, mileage: string, make: string, model: string, color: string, trim: string, bodyStyle: string, features: string, drivetrain: string}}
 */
function buildSdFilterSearchPayload() {
	var helperState = search.helper && search.helper.state ? search.helper.state : {};
	var status = "All";
	var certificationRefinements = getSdStateFilterValues(helperState, ["flags.type"]);

	if (certificationRefinements !== "All") {
		var selectedCount = certificationRefinements.split("|").length;
		var totalCount = 0;

		if (search.helper && search.helper.lastResults) {
			var facetValues = search.helper.lastResults.getFacetValues("flags.type");
			if (Array.isArray(facetValues)) {
				totalCount = facetValues.length;
			}
		}

		if (totalCount > 0 && selectedCount >= totalCount) {
			status = "Mixed";
		} else {
			status = "CPO";
		}
	} else if (srpCondition) {
		status = srpCondition;
	}

	/**
	 * Handle price, year, and mileage as special cases since they can be either a range facet refinement or a numeric slider refinement depending on how the user has interacted with the filters.
	 */
	var priceBounds = getSdPriceBounds(helperState);
	var year = getSdYearValue(helperState);

	var mileageRangeSelection = getSdStateFilterValues(helperState, ["mileageRange"]);
	var mileage = mileageRangeSelection !== "All" ? mileageRangeSelection : getSdNumericRangeValue(helperState, "mileage", function(v) { return Number(v).toLocaleString(); });

	return {
		status: status,
		minPrice: priceBounds.min,
		maxPrice: priceBounds.max,
		year: year,
		mileage: mileage,
		make: getSdStateFilterValues(helperState, ["make"]),
		model: getSdStateFilterValues(helperState, ["model"]),
		color: getSdStateFilterValues(helperState, ["genericColor", "generic_color"]),
		trim: getSdStateFilterValues(helperState, ["trim"]),
		bodyStyle: getSdStateFilterValues(helperState, ["body"]),
		features: getSdStateFilterValues(helperState, ["features"]),
		drivetrain: getSdStateFilterValues(helperState, ["drivetrain"])
	};
}

/**
 * Creates a stable signature for the current search helper state so we can
 * detect real SRP refinement changes across renders.
 *
 * This is used only as change detection. The actual Shift Digital payload is
 * still built separately from the supported helper refinements.
 *
 * @returns {string}
 */
function buildSdSearchStateSignature() {
	if (!search.helper || !search.helper.state) {
		return JSON.stringify({
			query: "",
			disjunctiveFacetsRefinements: {},
			facetsRefinements: {},
			hierarchicalFacetsRefinements: {},
			numericRefinements: {}
		});
	}

	return JSON.stringify({
		query: search.helper.state.query || "",
		disjunctiveFacetsRefinements: search.helper.state.disjunctiveFacetsRefinements || {},
		facetsRefinements: search.helper.state.facetsRefinements || {},
		hierarchicalFacetsRefinements: search.helper.state.hierarchicalFacetsRefinements || {},
		numericRefinements: search.helper.state.numericRefinements || {}
	});
}

/**
 * Builds a signature of only the facet/numeric refinement state (excludes
 * the search query) so facet-only changes can be distinguished from
 * query-only changes.
 *
 * @returns {string}
 */
function buildSdFacetStateSignature() {
	if (!search.helper || !search.helper.state) {
		return JSON.stringify({
			disjunctiveFacetsRefinements: {},
			facetsRefinements: {},
			hierarchicalFacetsRefinements: {},
			numericRefinements: {}
		});
	}

	return JSON.stringify({
		disjunctiveFacetsRefinements: search.helper.state.disjunctiveFacetsRefinements || {},
		facetsRefinements: search.helper.state.facetsRefinements || {},
		hierarchicalFacetsRefinements: search.helper.state.hierarchicalFacetsRefinements || {},
		numericRefinements: search.helper.state.numericRefinements || {}
	});
}

