	/**
	 * Retry counter lives outside the function on purpose.
	 *
	 * It used to be `let tries = 0` as the first statement inside, which reset it
	 * to zero on every call - so `tries < 10` could never fail and the "retry ten
	 * times" guard was in fact an unbounded one-second loop for as long as the page
	 * stayed open. It does not fire where DG loads normally, but it does on any
	 * dealer where DG is slow, blocked, or absent.
	 *
	 * Logging is behind ?spdebug=1 for the same reason the rest of this moved to
	 * onRenderSettled: console.log of a populated vehicle array on every render is
	 * not free, and it is markedly worse in Safari with an inspector attached -
	 * which is exactly the situation anyone debugging this on an iPhone is in.
	 */
	var smartPathTries = 0;
	var smartPathDebug = new URLSearchParams(window.location.search).get('spdebug') === '1';
	var smartPathCpoMakes = "";

	/**
	 * What SmartPath gets as salesClass and vehicleType: "cpo", or the condition lowercased. A used hit is cpo the way
	 * its card and its VDP decide it: certified, and of a make the dealer's "vehicle-cpo-makes" allows (empty allows
	 * every make), as nexusSmartPathSalesClass() does on the VDP. A live hit's certified is a boolean, never "yes".
	 */
	function smartPathSalesClass(veh, cpoMakes)
	{
		var condition = String(veh.condition || "").toLowerCase();
		var flags = veh.flags || {};
		var certified = [ veh.certified, flags.certified ].some(value => [ "true", "1", "yes" ].indexOf(String(value).trim().toLowerCase()) !== -1);
		var make = String(veh.make || "");
		var makeAllowed = cpoMakes === "" || (make !== "" && cpoMakes.indexOf(make) !== -1);

		return condition === "used" && certified && makeAllowed ? "cpo" : condition;
	}

