(function () {
  function hydrate() {
    // Only act on hosts we mark, and only when the shadow root isn't already present.
    var hosts = document.querySelectorAll('.platform-linked-content[data-platform-shadow="1"]');
    for (var i = 0; i < hosts.length; i++) {
      var host = hosts[i];
      if (host.shadowRoot || !host.attachShadow) continue;

      var t = host.querySelector('template[shadowrootmode]');
      if (!t) continue;

      var mode = t.getAttribute('shadowrootmode') || 'open';
      var root = host.attachShadow({ mode: mode });

      root.appendChild(t.content.cloneNode(true));
      t.remove();
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', hydrate);
  } else {
    hydrate();
  }
})();

