(function () {
        const menuRSBtns = document.querySelectorAll(".menu-rs-container .menu-item .item-btn");
        const menuItemHav = document.querySelectorAll(".menu-rs-container .menu-item.have-nav");

        menuRSBtns.forEach(function (item, index) {
            item.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                var drop = document.querySelectorAll(".menu-rs-container .menu-item .menu-drop")[index];
                if (drop) drop.classList.toggle('action');
                item.classList.toggle('action');
                item.closest('.menu-item').classList.toggle('active');
            });
        });

        menuItemHav.forEach(function (item) {
            var link = item.querySelector('.list-item');
            if (!link) return;
            link.addEventListener('click', function (e) {
                if (link.getAttribute('href') === '#') {
                    e.preventDefault();
                    item.classList.toggle('active');
                    var btn = item.querySelector('.item-btn');
                    if (btn) btn.classList.toggle('action');
                    var drop = item.querySelector('.menu-drop');
                    if (drop) drop.classList.toggle('action');
                }
            });
        });
    })();

const headerMenuRS = document.querySelector(".header-btn-rs")
    const menuRS = document.querySelector(".menu-rs")
    const btnCloseMenuRS = document.querySelector(".menu-rs-btn")
    const baseContainer = document.querySelector(".base-container")
    const siteHeader = document.querySelector("header")
    const headerPlaceholder = document.querySelector(".header-placeholder")
    const headerBottom = document.querySelector(".header-bottom")
    const btnGoToTop = document.querySelector(".p-fix-button .button-item.back-to-top")

    if (headerMenuRS) {
        headerMenuRS.addEventListener('click', () => {
            headerMenuRS.classList.add('active')
            menuRS.classList.add('show')
            baseContainer.classList.add('rs')
        })
    }

    if (btnCloseMenuRS) {
        btnCloseMenuRS.addEventListener('click', () => {
            menuRS.classList.remove('show')
            headerMenuRS.classList.remove('active')
            baseContainer.classList.remove('rs')
        })
    }

    function updateHeaderOnScroll() {
        const positionScroll = window.scrollY || document.documentElement.scrollTop

        if (positionScroll >= 150) {
            if (siteHeader && !siteHeader.classList.contains('fixed')) {
                if (headerPlaceholder) {
                    headerPlaceholder.style.height = siteHeader.offsetHeight + 'px'
                }
                siteHeader.classList.add('fixed')
            }
            if (headerBottom) headerBottom.classList.add('scroll')
            if (btnGoToTop) btnGoToTop.classList.add('show')
        } else {
            if (siteHeader) siteHeader.classList.remove('fixed')
            if (headerPlaceholder) headerPlaceholder.style.height = '0px'
            if (headerBottom) headerBottom.classList.remove('scroll')
            if (btnGoToTop) btnGoToTop.classList.remove('show')
        }
    }

    window.addEventListener('scroll', updateHeaderOnScroll)
    updateHeaderOnScroll()

    if (btnGoToTop) {
        btnGoToTop.addEventListener('click', () => {
            window.scrollTo(0, 0)
        })
    }

window.addEventListener('load', () => {
        const contactBtn = document.querySelector('.contact-button')

        if (contactBtn) {
            contactBtn.addEventListener('click', () => {
                contactBtn.classList.remove('show')
                window.scrollTo(0,0)
                setTimeout(() => {
                    document.querySelector('.contacts .content .form').classList.remove('fade-out')
                }, 100)
            })
        }
    })

const pHeadverItems = document.querySelectorAll(".p-headver .item")
    if (pHeadverItems) {
        pHeadverItems.forEach((item, index) => {
            item.addEventListener("click", () => {
                let pHeadverItemActive = document.querySelector(".p-headver .item.active")
                pHeadverItemActive.classList.remove('active')
                item.classList.add('active')

                const event = new CustomEvent('categoryTabChanged', {
                    detail: {
                        selectedIndex: index,
                    },
                    bubbles: true
                });
                item.closest('.p-headver').dispatchEvent(event);
            })
        })
    }

document.addEventListener('DOMContentLoaded', function () {
        const homeProductContainer = document.querySelector('.home-product-container');
        if (!homeProductContainer) {
            return;
        }

        const homeProductLists = homeProductContainer.querySelectorAll(".home-product-list");
        const homeProductBtns = homeProductContainer.querySelectorAll(".home-product-btn");

        function showProductTab(selectedIndex) {
            homeProductLists.forEach((item, index) => {
                item.classList.toggle("none", index !== selectedIndex);
            });
            homeProductBtns.forEach((item, index) => {
                item.classList.toggle("none", index !== selectedIndex);
            });
        }

        showProductTab(0);

        const ucContainer = homeProductContainer.querySelector('.p-headver');
        if (ucContainer) {
            ucContainer.addEventListener('categoryTabChanged', function (e) {
                showProductTab(e.detail.selectedIndex);
            });
        }
    });

