$(document).ready(function () {
            var popupImgSrc = $('#home-popup-img').attr('src');

            // Lấy đường dẫn URL hiện tại
            var path = window.location.pathname.toLowerCase();

            // Chỉ kiểm tra trang chủ là "/" hoặc "/default.aspx"
            var isHomePage = (path === '/' || path === '/default.aspx');

            var autoCloseTimer;

            // Nếu có link hình Popup VÀ đang ở trang chủ thì xử lý
            if (popupImgSrc && popupImgSrc.trim() !== "" && isHomePage) {

                // 1. Hiện Popup ngay lập tức
                $('#home-popup').addClass('show');

                // 2. Tự động tắt sau 30 giây (30000ms)
                autoCloseTimer = setTimeout(function () {
                    $('#home-popup').removeClass('show');
                }, 30000); 
            }

            // Hàm đóng popup và hủy bộ đếm giờ (nếu người dùng chủ động đóng trước 30s)
            function closePopup() {
                $('#home-popup').removeClass('show');
                if (autoCloseTimer) {
                    clearTimeout(autoCloseTimer); // Hủy đếm giờ để tối ưu bộ nhớ
                }
            }

            // Sự kiện click nút X để đóng
            $('.custom-popup-close').click(function () {
                closePopup();
            });

            // Click ra ngoài khoảng đen để đóng popup
            $('#home-popup').click(function (e) {
                if (e.target === this) {
                    closePopup();
                }
            });
        });

