document.addEventListener("DOMContentLoaded", function() {
    // Locate the form by name or ID
    var form = document.forms['form1'];

    // Define the calculate function to update input fields and total
    function calculate() {
        var total = 0;

        // Loop through each dropdown and calculate the total score
        for (let i = 1; i <= 10; i++) {
            const selectElement = form.querySelector(`[name="p${i}"]`);
            const value = parseInt(selectElement.value) || 0;  // Default to 0 if not a number
            form.querySelector(`[name="sp${i}"]`).value = value;  // Update corresponding input field
            total += value;
        }

        // Update the total field with the cumulative score
        form.querySelector('[name="total"]').value = total;

        // Enable or disable the Submit button based on total score
        if (total >= 400) {
            form.querySelector('[name="Submit1"]').disabled = false;
            form.querySelector('[name="Submit1"]').onclick = function() {
                window.location.href = 'https://lscms.org/success';
            };
        } else {
            form.querySelector('[name="Submit1"]').disabled = true;
            form.querySelector('[name="Submit1"]').onclick = null;  // Clear action if total is insufficient
        }
    }

    // Attach calculate function to all dropdowns' onchange event
    form.querySelectorAll("select").forEach(select => {
        select.addEventListener("change", calculate);
    });
});

