          options: [
            ["None", 0],
            ["1 program", 25],
            ["2 programs", 50],
            ["3 programs", 75],
            ["4 or more programs", 100]
          ]
        },
        {
          id: "memberships",
          label: "Professional membership of supply chain/logistics associations",
          options: [
            ["None", 0],
            ["1 year", 10],
            ["2 years", 20],
            ["3 years", 30],
            ["4 years", 40],
            ["5 years or more", 50]
          ]
        },
        {
          id: "cpd",
          label: "Association CPD activities during the past three years",
          options: [
            ["None", 0],
            ["1 activity", 10],
            ["2 activities", 20],
            ["3 activities", 30],
            ["4 activities", 40],
            ["5 activities", 50],
            ["6 activities", 60],
            ["7 activities", 70],
            ["8 activities", 80],
            ["9 activities", 90],
            ["10 or more activities", 100]
          ]
        },
        {
          id: "leadership",
          label: "Leadership roles in the industry during the past three years",
          options: [
            ["None", 0],
            ["1 position", 15],
            ["2 positions", 30],
            ["3 or more positions", 45]
          ]
        },
        {
          id: "participation",
          label: "Supply chain/logistics industry participation and contributions",
          options: [
            ["None", 0],
            ["1 unpublished contribution", 15],
            ["2 unpublished contributions", 30],
            ["3 unpublished contributions", 45],
            ["4 or more unpublished contributions", 60]
          ]
        },
        {
          id: "publications",
          label: "Supply chain/logistics industry publications",
          options: [
            ["None", 0],
            ["1 published contribution", 40],
            ["2 or more published contributions", 60]
          ]
        },
        {
          id: "awards",
          label: "Supply chain/logistics recognition or awards",
          options: [
            ["None", 0],
            ["1 award", 15],
            ["2 awards", 30],
            ["3 awards", 45],
            ["4 or more awards", 60]
          ]
        }
      ];

      function buildCalculator(root) {
        var fields = root.querySelector("[data-clp-fields]");
        var scoreOutput = root.querySelector("[data-clp-score]");
        var status = root.querySelector("[data-clp-status]");
        var message = root.querySelector("[data-clp-message]");
        var apply = root.querySelector("[data-clp-apply]");
        var breakdown = root.querySelector("[data-clp-breakdown]");
        var form = root.querySelector("[data-clp-form]");
        var calculateButton = root.querySelector("[data-clp-calculate]");

        criteria.forEach(function (criterion) {
          var field = document.createElement("div");
          field.className = "lscms-clp__field";

          var label = document.createElement("label");
          label.setAttribute("for", "clp-" + criterion.id);
          label.textContent = criterion.label;

          var select = document.createElement("select");
          select.id = "clp-" + criterion.id;
          select.name = criterion.id;
          select.setAttribute("data-clp-select", criterion.id);

          criterion.options.forEach(function (option) {
            var optionNode = document.createElement("option");
            optionNode.value = option[1];
            optionNode.textContent = option[0] + " (" + option[1] + " pts)";
            select.appendChild(optionNode);
          });

          field.appendChild(label);
          field.appendChild(select);
          fields.appendChild(field);
        });

        function getSelectedData() {
          return criteria.map(function (criterion) {
            var select = form.querySelector("[data-clp-select='" + criterion.id + "']");
            var points = parseInt(select.value, 10) || 0;
            var max = criterion.options[criterion.options.length - 1][1];
            var selectedLabel = select.options[select.selectedIndex].text.replace(/\s\([0-9]+ pts\)$/, "");
            return {
              label: criterion.label,
              selectedLabel: selectedLabel,
              points: points,
              max: max
            };
          });
        }

        function getAdvice(selectedData, needed) {
          var gaps = selectedData
            .filter(function (item) {
              return item.points < item.max;
            })
            .sort(function (a, b) {
              return (b.max - b.points) - (a.max - a.points);
            })
            .slice(0, 2)
            .map(function (item) {
              return item.label.toLowerCase();
            });

          if (!gaps.length) {
            return "Review your supporting evidence before submitting your formal application.";
          }

          return "You need " + needed + " more points. Consider strengthening " + gaps.join(" and ") + ", and engage with LSCMS or your nominated industry association for relevant CPD activities.";
        }

        function update() {
          var selectedData = getSelectedData();
          var total = selectedData.reduce(function (sum, item) {
            return sum + item.points;
          }, 0);
          var percent = Math.min(100, Math.round((total / passScore) * 100));
          var name = form.elements.name.value.trim();
          var prefix = name ? name + ", you" : "You";
          var qualified = total >= passScore;
          var near = total >= 300 && total < passScore;
          var needed = Math.max(0, passScore - total);

          scoreOutput.value = total;
          root.style.setProperty("--score-percent", percent + "%");

          status.classList.toggle("is-qualified", qualified);
          status.classList.toggle("is-near", near);

          if (qualified) {
            status.textContent = "Meets 400-point guide";
            message.textContent = "Congratulations. " + prefix + " scored " + total + " points, which meets the guide for CLP/CLE certification. Complete the formal application so your assessment can be verified.";
            apply.classList.add("is-visible");
          } else {
            status.textContent = near ? "Close to qualifying" : "Below 400-point guide";
            message.textContent = prefix + " scored " + total + " points. " + getAdvice(selectedData, needed);
            apply.classList.remove("is-visible");
          }

          breakdown.innerHTML = "";
          selectedData.forEach(function (item) {
            var row = document.createElement("div");
            var label = document.createElement("span");
            var points = document.createElement("strong");
            row.className = "lscms-clp__breakdown-row";
            label.textContent = item.label;
            points.textContent = item.points;
            row.appendChild(label);
            row.appendChild(points);
            breakdown.appendChild(row);
          });
        }

        form.addEventListener("change", update);
        form.addEventListener("reset", function () {
          window.setTimeout(update, 0);
        });
        calculateButton.addEventListener("click", update);
        update();
      }

      document.querySelectorAll("[data-clp-calculator]").forEach(buildCalculator);
    }());

