              // Safari 26+ Fingerprinting Protection Fix
              // Safari 26 blocks scripts from reading document.referrer
              // Server-side middleware captures it and puts in cookie
              // This script copies cookie to localStorage for analytics code
              (function() {
                var isDev = window.location.hostname === 'localhost' || window.location.hostname.includes('vercel.app');
                try {
                  // Read referrer from server-set cookie (Safari can't block cookies)
                  var cookieMatch = document.cookie.match(/external_referrer=([^;]+)/);
                  if (cookieMatch) {
                    var cookieData = decodeURIComponent(cookieMatch[1]);
                    // Copy to localStorage so existing analytics code can find it
                    localStorage.setItem('external_referrer', cookieData);

                    // Also set backup in sessionStorage AND sync session_id
                    try {
                      var parsed = JSON.parse(cookieData);
                      if (parsed.referrer) {
                        sessionStorage.setItem('backup_referrer', parsed.referrer);

                        // CRITICAL: Sync session_id from cookie to sessionStorage
                        // This ensures getReferrerFromCookie() validation succeeds
                        if (parsed.sessionId) {
                          sessionStorage.setItem('session_id', parsed.sessionId);
                        }

                        if (isDev) {
                          console.log('[Client Script] Referrer from server cookie:', {
                            referrer: parsed.referrer,
                            sessionId: parsed.sessionId,
                            source: 'server-cookie',
                            documentReferrer: document.referrer || '(blocked or empty)',
                          });
                        }
                      }
                    } catch(e) {}
                  }

                  // Fallback: try document.referrer (works on non-Safari 26 browsers)
                  if (!cookieMatch && document.referrer) {
                    var sessionId = sessionStorage.getItem('session_id') || Date.now() + '_' + Math.random().toString(36).slice(2);
                    var data = JSON.stringify({
                      referrer: document.referrer,
                      sessionId: sessionId,
                      timestamp: Date.now()
                    });
                    sessionStorage.setItem('session_id', sessionId);
                    localStorage.setItem('external_referrer', data);
                    sessionStorage.setItem('backup_referrer', document.referrer);

                    if (isDev) {
                      console.log('[Client Script] Referrer from document.referrer:', {
                        referrer: document.referrer,
                        source: 'document.referrer',
                      });
                    }
                  }

                  // Log if no referrer found (direct entry or Safari 26 blocked both)
                  if (!cookieMatch && !document.referrer && isDev) {
                    console.log('[Client Script] No referrer found:', {
                      hasCookie: !!cookieMatch,
                      hasDocumentReferrer: !!document.referrer,
                      possiblyBlocked: navigator.userAgent.includes('Safari') && !navigator.userAgent.includes('Chrome'),
                    });
                  }
                } catch (e) {
                  if (isDev) console.error('[Client Script] Error:', e);
                }
              })();
