jQuery(function ($) {

    /* Equal Heights  ***********
    **************************/
    equalheight = function (container) {

        var currentTallest = 0,
            currentRowStart = 0,
            rowDivs = new Array(),
            $el,
            topPosition = 0;
        $(container).each(function () {

            $el = $(this);
            $($el).height('auto')
            topPostion = $el.position().top;

            if (currentRowStart != topPostion) {
                for (currentDiv = 0; currentDiv < rowDivs.length; currentDiv++) {
                    rowDivs[currentDiv].height(currentTallest);
                }
                rowDivs.length = 0; // empty the array
                currentRowStart = topPostion;
                currentTallest = $el.height();
                rowDivs.push($el);
            } else {
                rowDivs.push($el);
                currentTallest = (currentTallest < $el.height()) ? ($el.height()) : (currentTallest);
            }
            for (currentDiv = 0; currentDiv < rowDivs.length; currentDiv++) {
                rowDivs[currentDiv].height(currentTallest);
            }
        });
    }

    // Hide Google Reviews
    function hideReviews() {        

        const hideByNameArray = ["Stan Mosley"]

        document.querySelectorAll('.grw-review')
            .forEach(review => {
                let personName = review.querySelector('.wp-gr.wpac a.wp-google-name');
                let personNameText =  personName.textContent || personName.innerText;

                if (hideByNameArray.includes(personNameText)) {
                    console.log("Remove Review");
                    review.remove();
                }
        });

        // const imageArray = ["img[title='Kellie Matherne']", "img[title='Susie Noel']"]

        // imageArray.forEach(imgSelector => {
