    }

    function toggleReviews(minReviewCount) {

        currentReviewCount = document.querySelectorAll('.wp-google-review').length - document.querySelectorAll('.wp-google-hide').length;
        console.log("current", currentReviewCount)

        // Show reviews based on minimum review count
        document.querySelectorAll('.wp-google-hide')
            .forEach(review => {

                if (currentReviewCount < minReviewCount) {
                    review.classList.remove("wp-google-hide")
                    currentReviewCount++;
                    console.log("current fired")
                }

            })
    }

    // Limit Contact Us form phone field to no more than 10 numbers
    $('#field_3nqtm').on('input', function () {
        var input = $(this).val();
        // Remove all non-digit characters except hyphens
        var digits = input.replace(/[^0-9]/g, '');

        // If more than 10 digits are entered, trim the input
        if (digits.length > 10) {
            // Remove excess digits, keeping the first 10
            var trimmedDigits = digits.substring(0, 10);

            // Reconstruct the input value with only the allowed digits and hyphens
            var trimmedInput = '';
            var digitIndex = 0;
            for (var i = 0; i < input.length; i++) {
                if (input[i].match(/[0-9]/)) {
                    if (digitIndex < 10) {
                        trimmedInput += trimmedDigits[digitIndex++];
                    }
                } else {
                    trimmedInput += input[i];
                }
            }

            $(this).val(trimmedInput);
        }
    });

    $(window).resize(function () {
        equalheight('.service-card');
        equalheight('.service-card-icon');
    });


    equalheight('.service-card');
    equalheight('.service-card-icon');    
    hideReviews();

});

