document.addEventListener('DOMContentLoaded', function () {
        console.log("DOM fully loaded.");

        // 5) Load the YouTube IFrame API if needed
        function loadYouTubeAPI() {
            if (!window.YT || !window.YT.Player) {
                console.log("Inserting <script> for YouTube IFrame API...");
                const tag = document.createElement('script');
                tag.src = "https://www.youtube.com/iframe_api";
                document.head.appendChild(tag);
            } else {
                console.log("YT API already present; calling onYouTubeIframeAPIReady() now.");
                onYouTubeIframeAPIReady();
            }
        }

        // 6) YouTube will call this when its API is ready
        window.onYouTubeIframeAPIReady = function () {
            console.log(">> YouTube IFrame API is ready (onYouTubeIframeAPIReady).");
            initializePlayer();
        };

        function initializePlayer() {
            console.log("initializePlayer() running...");
            const iframeElem = document.getElementById('myYouTubeIframe');
            if (!iframeElem) {
                console.warn("❌ No iframe with ID #myYouTubeIframe found.");
                return;
            }
            console.log("✔️ Found #myYouTubeIframe:", iframeElem);

            const wrapper = document.querySelector('.uabb-video__outer-wrap');
            if (!wrapper) {
                console.warn("❌ .uabb-video__outer-wrap not found.");
                return;
            }
            console.log("✔️ Found wrapper .uabb-video__outer-wrap.");

            // 7) Create and style the button
            const soundToggle = document.createElement('button');
            soundToggle.id = "soundToggle";
            // soundToggle.textContent = "Click for Sound";
            soundToggle.innerHTML = 'Click for Sound <i class="fas fa-volume-up" aria-hidden="true"></i>';

            soundToggle.disabled = true;
            wrapper.appendChild(soundToggle);
            console.log("✔️ Appended #soundToggle (disabled).");

            // 8) Instantiate the YouTube Player object
            const player = new YT.Player('myYouTubeIframe', {
                events: {
                    onReady: function (event) {
                        console.log(">> YT.Player onReady() callback fired.");
                        event.target.mute();
                        console.log("→ Video has been muted by code.");
                        soundToggle.disabled = false;
                        console.log("→ soundToggle.disabled = false; button should now be clickable.");
                    }
                }
            });

            // 9) Attach a click listener with logs
            soundToggle.addEventListener('click', function () {
                console.log(">> soundToggle click handler fired.");
                console.log("→ Calling player.seekTo(0), playVideo(), unMute().");
                player.seekTo(0);
                player.playVideo();
                player.unMute();
                soundToggle.style.display = 'none';
                console.log("→ Button hidden.");

                // Optional: remove any pseudo-overlay via CSS
                const styleTag = document.createElement('style');
                styleTag.innerHTML = `.uabb-video__outer-wrap::after { content: none !important; }`;
                document.head.appendChild(styleTag);
                console.log("→ Added CSS to hide .uabb-video__outer-wrap::after.");
            });
        }

        loadYouTubeAPI();
    });

