(function () {
        "use strict";

        // ---- Konfiguration -------------------------------------------------------
        var HOLD_MS = 3000; // Anzeigedauer pro Logo (Tick-Intervall)
        var STAGGER_MS = 100; // Zeitversatz zwischen den Spalten (Ripple)
        var SHIFT = "1.5rem"; // subtiler Versatz beim Ein-/Ausblenden (CSS-Wert inkl. Einheit)

        var GRID_SEL = ".partner-tools-slim_grid-wrap";
        var WRAP_SEL = ".partner-tools-slim_wrap";
        var ITEM_SEL = ".partner-tools-slim_item";

        var reduceMotion =
            window.matchMedia &&
            window.matchMedia("(prefers-reduced-motion: reduce)").matches;

        function init() {
            var grids = document.querySelectorAll(GRID_SEL);
            if (!grids.length) return;
            Array.prototype.forEach.call(grids, setupGrid);
        }

        function setupGrid(grid) {
            var wraps = Array.prototype.slice.call(
                grid.querySelectorAll(WRAP_SEL),
            );
            if (!wraps.length) return;

            var STEP = wraps.length; // "Seitenweise": Sprung = Spaltenanzahl

            // Pro Spalte eigene Item-Liste + Startindex (= Spaltenindex)
            var cols = wraps.map(function (wrap, k) {
                var items = Array.prototype.slice.call(
                    wrap.querySelectorAll(ITEM_SEL),
                );
                return {
                    items: items,
                    current: items.length ? k % items.length : 0,
                };
            });

            // Startzustand ohne Animation setzen (kein Flash beim Laden)
            cols.forEach(function (col) {
                col.items.forEach(function (item, i) {
                    place(item, i === col.current ? "active" : "below", true);
                });
            });

            // Reduzierte Bewegung: statisch lassen, nicht animieren
            if (reduceMotion) return;

            var tick = 0;
            var timer = null;
            var isVisible = false;

            function advance() {
                tick += 1;
                cols.forEach(function (col, k) {
                    if (col.items.length < 2) return;
                    var nextIndex = (tick * STEP + k) % col.items.length;
                    if (nextIndex === col.current) return;
                    window.setTimeout(
                        flip.bind(null, col, nextIndex),
                        k * STAGGER_MS,
                    );
                });
            }

            function flip(col, nextIndex) {
                var outItem = col.items[col.current];
                var inItem = col.items[nextIndex];

                // Eingehendes Item ohne Transition nach unten resetten ...
                place(inItem, "below", true);
                void inItem.offsetHeight; // Reflow erzwingen
                place(inItem, "active", false); // ... dann animiert einblenden

                // Aktuelles Item nach oben rausschieben + ausblenden
                place(outItem, "out", false);

                col.current = nextIndex;
            }

            function start() {
                if (timer) return;
                timer = window.setInterval(advance, HOLD_MS);
            }
            function stop() {
                if (!timer) return;
                window.clearInterval(timer);
                timer = null;
            }

            // Pause bei Tab-Wechsel
            document.addEventListener("visibilitychange", function () {
                if (document.hidden) stop();
                else if (isVisible) start();
            });

            // Pause außerhalb des Viewports
            if ("IntersectionObserver" in window) {
                new IntersectionObserver(
                    function (entries) {
                        entries.forEach(function (entry) {
                            isVisible = entry.isIntersecting;
                            if (isVisible && !document.hidden) start();
                            else stop();
                        });
                    },
                    { threshold: 0.1 },
                ).observe(grid);
            } else {
                isVisible = true;
                start();
            }
        }

        // Setzt einen Item-Zustand. snap=true → ohne Animation (Reset).
        function place(item, state, snap) {
            item.style.transition = snap ? "none" : "";
            switch (state) {
                case "active":
                    item.style.transform = "translate3d(0, 0, 0)";
                    item.style.opacity = "1";
                    break;
                case "below":
                    item.style.transform = "translate3d(0, " + SHIFT + ", 0)";
                    item.style.opacity = "0";
                    break;
                case "out":
                    item.style.transform =
                        "translate3d(0, -" + SHIFT + ", 0)";
                    item.style.opacity = "0";
                    break;
            }
        }

        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", init);
        } else {
            init();
        }
    })();

