(function () {
  var target = document.querySelector('.typedjs-multiple');
  if (!target) return;

  // Reduced Motion: statischer Text statt Endlos-Animation.
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    target.innerHTML = 'Ideen.';
    return;
  }

  var TYPED_SRC = 'https://files.ideenhunger.com/src/ideenhunger/js/typed.js';
  var instance = null;
  var loading = false;

  function init() {
    if (typeof window.Typed !== 'function') return;
    instance = new window.Typed('.typedjs-multiple', {
      strings: ['Ideen.', '&nbsp;', 'Erfolgen.', '&nbsp;', 'Awards.', '&nbsp;'],
      startDelay: 250,
      typeSpeed: 150,
      backSpeed: 80,
      backDelay: 1750,
      loop: true
    });
  }

  function load() {
    if (loading) return;
    loading = true;
    var s = document.createElement('script');
    s.src = TYPED_SRC;
    s.onload = init;
    document.head.appendChild(s);
  }

  if (!('IntersectionObserver' in window)) { load(); return; }

  new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (entry.isIntersecting) {
        if (!instance) load();
        else instance.start();
      } else if (instance) {
        instance.stop();
      }
    });
  }, { rootMargin: '200px 0px' }).observe(target);
})();

(function () {
  var marquees = document.querySelectorAll('[data-css-marquee]');
  if (!marquees.length) return;

  var PIXELS_PER_SECOND = 35;

  function init() {
    var lists = [];

    marquees.forEach(function (marquee) {
      marquee.querySelectorAll('[data-css-marquee-list]').forEach(function (list) {
        marquee.appendChild(list.cloneNode(true));
      });
    });

    // Lesen …
    marquees.forEach(function (marquee) {
      marquee.querySelectorAll('[data-css-marquee-list]').forEach(function (list) {
        lists.push({ el: list, width: list.offsetWidth });
      });
    });

    // … dann schreiben.
    lists.forEach(function (item) {
      item.el.style.animationDuration = (item.width / PIXELS_PER_SECOND) + 's';
      item.el.style.animationPlayState = 'paused';
    });

    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        entry.target.querySelectorAll('[data-css-marquee-list]').forEach(function (list) {
          list.style.animationPlayState = entry.isIntersecting ? 'running' : 'paused';
        });
      });
    }, { threshold: 0 });

    marquees.forEach(function (m) { observer.observe(m); });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
})();

