                                      -> sichtbar, WÄHREND das Video steht
     Sichtbarkeit über das hidden-Attribut, ausgewertet von
     .w-background-video--control > [hidden] { display:none !important }
     in webflow.css. Kein eigenes CSS nötig.                          */
  Array.prototype.forEach.call(wrappers, function (wrap, index) {
    var btn = wrap.querySelector('[data-w-bg-video-control]');
    var video = wrap.querySelector('video');
    if (!btn || !video) return;

    var whilePlaying = btn.querySelector('.bg-video_control_play-state');
    var whilePaused  = btn.querySelector('.bg-video_control_pause-state');

    // aria-controls zeigte auf die entfernte Webflow-ID – neu verknüpfen.
    if (!video.id) video.id = 'bg-video-' + (index + 1);
    btn.setAttribute('aria-controls', video.id);

    function sync() {
      var running = !video.paused;
      if (whilePlaying) whilePlaying.hidden = !running;
      if (whilePaused)  whilePaused.hidden  = running;
      btn.setAttribute('aria-label',
        running ? 'Hintergrundvideo pausieren' : 'Hintergrundvideo abspielen');
    }

    btn.addEventListener('click', function (e) {
      // WICHTIG: Webflow hat einen delegierten jQuery-Klick-Handler auf
      // document, der dieses Video sofort wieder startet. Ohne
      // stopPropagation() pausiert das Video und läuft im selben Klick
      // wieder an – der Button wirkt dann funktionslos.
      e.stopPropagation();
      if (video.paused) play(video); else video.pause();
    });

    video.addEventListener('play', sync);
    video.addEventListener('pause', sync);
    sync();
  });

  /* --- Lazy Loading -------------------------------------------------
     Reduced Motion: nicht automatisch laden. Der Button bleibt nutzbar,
     wer will, startet das Video selbst.                              */
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  if (!('IntersectionObserver' in window)) {
    Array.prototype.forEach.call(wrappers, function (w) {
      var v = w.querySelector('video');
      if (v) play(v);
    });
    return;
  }

  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      io.unobserve(entry.target);
      var v = entry.target.querySelector('video');
      if (v) play(v);
    });
  }, { rootMargin: '200px 0px' });

  Array.prototype.forEach.call(wrappers, function (w) { io.observe(w); });
})();

$(document).ready(function () {
    $('.w-dropdown').each(function () {
      const dropdown   = this;
      const $dropdown  = $(dropdown);
      const toggle     = $dropdown.find('.w-dropdown-toggle')[0];
      const $toggle    = $(toggle);

      // All focusable elements inside this dropdown, incl. the toggle
      const focusableElements = $dropdown.find(
        'a, button, .w-dropdown-toggle, [tabindex]:not([tabindex="-1"])'
      );

      /* ---------- helpers ---------- */
      function triggerEnterKey (element) {
        element.dispatchEvent(
          new KeyboardEvent('keydown', {
            bubbles   : true,
            cancelable: true,
            key       : 'Enter',
            code      : 'Enter',
            keyCode   : 13,
            which     : 13
          })
        );
      }

      function closeDropdown () {
        if (toggle.classList.contains('w--open')) {
          triggerEnterKey(toggle);   // let Webflow do the closing
        }
      }

      /* ---------- TAB / Shift+TAB handling (unchanged) ---------- */
      // Forward tab out of the last dropdown link
      focusableElements.last().on('keydown', function (e) {
        if (e.key === 'Tab' && !e.shiftKey) {
          setTimeout(() => {
            if (!$dropdown.find(':focus').length) closeDropdown();
          }, 0);
        }
      });

      // Reverse tab out of the first dropdown link
      focusableElements.first().on('keydown', function (e) {
        if (e.key === 'Tab' &&  e.shiftKey) {
          setTimeout(() => {
            if (!$dropdown.find(':focus').length) closeDropdown();
          }, 0);
        }
      });

      // Reverse tab off the toggle itself
      $toggle.on('keydown', function (e) {
        if (e.key === 'Tab' &&  e.shiftKey) {
          setTimeout(() => {
            if (!$dropdown.find(':focus').length) closeDropdown();
          }, 0);
        }
      });

      /* ---------- NEW: screen-reader / arrow-key support ---------- */
      $dropdown.on('focusout', function () {
        // Wait for the next element to receive focus
        setTimeout(() => {
          if (!$dropdown.find(':focus').length) {
            closeDropdown();         // focus moved outside → close
          }
        }, 0);
      });
    });
  });

window.ihMotion = (function () {
    const storageKey = 'ih-motion-paused';
    const listeners = [];
    let stored = null;

    try {
      stored = sessionStorage.getItem(storageKey);
    } catch (e) {}

    let paused = stored !== null ? stored === '1' : window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    const apply = () => {
      document.documentElement.setAttribute('data-motion', paused ? 'paused' : 'running');

      document.querySelectorAll('[data-motion-toggle]').forEach((btn) => {
        btn.setAttribute('aria-pressed', paused ? 'true' : 'false');
      });

      listeners.forEach((fn) => fn(paused));
    };

    const set = (value) => {
      paused = value;
      try {
        sessionStorage.setItem(storageKey, paused ? '1' : '0');
      } catch (e) {}
      apply();
    };

    document.documentElement.setAttribute('data-motion', paused ? 'paused' : 'running');

    document.addEventListener('DOMContentLoaded', () => {
      document.querySelectorAll('[data-motion-toggle]').forEach((btn) => {
        const isButton = btn.tagName === 'BUTTON';

        if (isButton) {
          btn.type = 'button';
        } else {
          btn.setAttribute('role', 'button');
          if (!btn.hasAttribute('tabindex')) btn.setAttribute('tabindex', '0');
        }

        btn.addEventListener('click', (e) => {
          e.preventDefault();
          set(!paused);
        });

        if (!isButton) {
          btn.addEventListener('keydown', (e) => {
            if (e.key !== 'Enter' && e.key !== ' ') return;
            e.preventDefault();
            set(!paused);
          });
        }
      });

      apply();
    });

    return {
      isPaused: () => paused,
      onChange: (fn) => listeners.push(fn),
    };
  })();

document.addEventListener('DOMContentLoaded', () => {
    const pausedByMotion = new Set();

    const getVideos = () => [...document.querySelectorAll('.w-background-video video')].filter((video) => !video.closest('[data-hover-video]'));

    const pauseVideos = () => {
      getVideos().forEach((video) => {
        if (video.paused && !video.autoplay) return;
        pausedByMotion.add(video);
        video.pause();
      });
    };

    const resumeVideos = () => {
      pausedByMotion.forEach((video) => video.play().catch(() => {}));
      pausedByMotion.clear();
    };

    document.addEventListener(
      'play',
      (e) => {
        const video = e.target;
        if (!(video instanceof HTMLVideoElement) || !window.ihMotion.isPaused()) return;
        if (!video.closest('.w-background-video')) return;
        if (video.closest('[data-hover-video], [data-bg-video]')) return;

        pausedByMotion.add(video);
        video.pause();
      },
      true,
    );

    if (window.ihMotion.isPaused()) pauseVideos();
    window.ihMotion.onChange((paused) => (paused ? pauseVideos() : resumeVideos()));
  });

function initLogoWallCycle() {
    const loopDelay = 1.5;
    const duration = 0.9;
    const shuffleFade = 0.3;

    document.querySelectorAll('[data-logo-wall-cycle-init]').forEach((root) => {
      const list = root.querySelector('[data-logo-wall-list]');
      const items = Array.from(list.querySelectorAll('[data-logo-wall-item]'));
      const shuffleBtn = root.querySelector('[data-logo-wall-shuffle-btn]') || root.closest('section')?.querySelector('[data-logo-wall-shuffle-btn]');

      const shuffleFront = root.getAttribute('data-logo-wall-shuffle') !== 'false';
      const originalTargets = items.map((item) => item.querySelector('[data-logo-wall-target]')).filter(Boolean);

      let visibleItems = [];
      let visibleCount = 0;
      let pool = [];
      let pattern = [];
      let patternIndex = 0;
      let inView = false;
      let tl;

      const syncPlayback = () => {
        if (!tl) return;
        inView && !document.hidden && !window.ihMotion.isPaused() ? tl.play() : tl.pause();
      };

      const getParent = (item) => item.querySelector('[data-logo-wall-target-parent]') || item;

      function isVisible(el) {
        return window.getComputedStyle(el).display !== 'none';
      }

      function shuffleArray(arr) {
        const a = arr.slice();
        for (let i = a.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [a[i], a[j]] = [a[j], a[i]];
        }
        return a;
      }

      function setup() {
        if (tl) {
          tl.kill();
        }
        visibleItems = items.filter(isVisible);
        visibleCount = visibleItems.length;

        pattern = shuffleArray(Array.from({ length: visibleCount }, (_, i) => i));
        patternIndex = 0;

        items.forEach((item) => {
          item.querySelectorAll('[data-logo-wall-target]').forEach((old) => old.remove());
        });

        pool = originalTargets.map((n) => n.cloneNode(true));

        let front, rest;
        if (shuffleFront) {
          const shuffledAll = shuffleArray(pool);
          front = shuffledAll.slice(0, visibleCount);
          rest = shuffleArray(shuffledAll.slice(visibleCount));
        } else {
          front = pool.slice(0, visibleCount);
          rest = shuffleArray(pool.slice(visibleCount));
        }
        pool = front.concat(rest);

        for (let i = 0; i < visibleCount; i++) {
          getParent(visibleItems[i]).appendChild(pool.shift());
        }

        tl = gsap.timeline({ repeat: -1, repeatDelay: loopDelay, paused: true });
        tl.call(swapNext);
        syncPlayback();
      }

      function swapNext() {
        const nowCount = items.filter(isVisible).length;
        if (nowCount !== visibleCount) {
          setup();
          return;
        }
        if (!pool.length) return;

        const idx = pattern[patternIndex % visibleCount];
        patternIndex++;

        const container = visibleItems[idx];
        const parent = container.querySelector('[data-logo-wall-target-parent]') || container.querySelector('*:has(> [data-logo-wall-target])') || container;
        const existing = parent.querySelectorAll('[data-logo-wall-target]');
        if (existing.length > 1) return;

        const current = parent.querySelector('[data-logo-wall-target]');
        const incoming = pool.shift();

        gsap.set(incoming, { yPercent: 50, autoAlpha: 0 });
        parent.appendChild(incoming);

        if (current) {
          gsap.to(current, {
            yPercent: -50,
            autoAlpha: 0,
            duration,
            ease: 'expo.inOut',
            onComplete: () => {
              current.remove();
              pool.push(current);
            },
          });
        }

        gsap.to(incoming, {
          yPercent: 0,
          autoAlpha: 1,
          duration,
          delay: 0.1,
          ease: 'expo.inOut',
        });
      }

      function shuffleAll() {
        if (items.filter(isVisible).length !== visibleCount) {
          setup();
          return;
        }

        const current = [];

        visibleItems.forEach((item) => {
          const targets = [...getParent(item).querySelectorAll('[data-logo-wall-target]')];
          gsap.killTweensOf(targets);
          targets.forEach((target) => {
            gsap.set(target, { clearProps: 'transform,opacity,visibility' });
            target.remove();
          });
          if (targets.length) current.push(targets[targets.length - 1]);
          if (targets.length > 1) pool.push(...targets.slice(0, -1));
        });

        const fresh = shuffleArray(pool);
        const next = fresh.slice(0, visibleCount);
        pool = shuffleArray(fresh.slice(visibleCount).concat(current));

        visibleItems.forEach((item, i) => {
          const target = next[i] || pool.shift();
          if (!target) return;
          gsap.set(target, { autoAlpha: 0 });
          getParent(item).appendChild(target);
          gsap.to(target, { autoAlpha: 1, duration: shuffleFade, ease: 'power1.out' });
        });
      }

      setup();

      ScrollTrigger.create({
        trigger: root,
        start: 'top bottom',
        end: 'bottom top',
        onToggle: (self) => {
          inView = self.isActive;
          syncPlayback();
        },
      });

      if (shuffleBtn) {
        if (shuffleBtn.tagName === 'BUTTON') shuffleBtn.type = 'button';
        shuffleBtn.addEventListener('click', (e) => {
          e.preventDefault();
          shuffleAll();
        });
      }

      document.addEventListener('visibilitychange', syncPlayback);
      window.ihMotion.onChange(syncPlayback);
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    initLogoWallCycle();
  });

function initRadialCardsSlider() {
    document.querySelectorAll('[data-radial-slider-init]').forEach((container) => {
      if (container._radialSliderDraggable) container._radialSliderDraggable.kill();
      if (container._radialSliderProxy) gsap.killTweensOf(container._radialSliderProxy);
      if (container._radialSliderProxyEl) container._radialSliderProxyEl.remove();
      if (container._radialSliderAutoplay) container._radialSliderAutoplay.kill();
      if (container._radialSliderTick) gsap.ticker.remove(container._radialSliderTick);

      const collection = container.querySelector('[data-radial-slider-collection]');
      const track = container.querySelector('[data-radial-slider-list]');
      if (!collection || !track) return;

      container.querySelectorAll('[data-radial-slider-clone]').forEach((el) => el.remove());

      const originalItems = Array.from(container.querySelectorAll('[data-radial-slider-item]:not([data-radial-slider-clone])'));
      if (!originalItems.length) return;

      container.setAttribute('role', 'region');
      container.setAttribute('aria-roledescription', 'carousel');
      container.setAttribute('aria-label', container.getAttribute('aria-label') || 'Radial Cards Slider');

      track.setAttribute('role', 'group');
      track.setAttribute('aria-label', 'Slides');

      originalItems.forEach((item, index) => {
        item.removeAttribute('data-radial-slider-item-status');
        item.removeAttribute('aria-hidden');
        item.setAttribute('role', 'group');
        item.setAttribute('aria-label', `Slide ${index + 1} of ${originalItems.length}`);
      });

      track.style.height = '';

      const mod = (value, total) => ((value % total) + total) % total;

      const containerStyles = getComputedStyle(container);
      const rotateStep = Math.abs(parseFloat(containerStyles.getPropertyValue('--slider-rotate'))) || 18;
      const maxLoopItems = Math.max(1, Math.floor(360 / rotateStep));

      const firstRect = originalItems[0].getBoundingClientRect();
      const itemWidth = firstRect.width;
      const itemHeight = firstRect.height;

      const originParts = getComputedStyle(originalItems[0]).transformOrigin.split(' ');
      const originY = parseFloat(originParts[1]) || itemHeight * 3.75;
      const wheelRadius = Math.max(0, originY - itemHeight / 2);
      const proxyRadius = wheelRadius + Math.max(itemWidth, itemHeight) * 0.525;

      const getBoundsAtAngle = (angle) => {
        const rad = (angle * Math.PI) / 180;

        return {
          x: Math.sin(rad) * wheelRadius,
          y: originY - Math.cos(rad) * wheelRadius,
          halfWidth: (Math.abs(Math.cos(rad)) * itemWidth) / 2 + (Math.abs(Math.sin(rad)) * itemHeight) / 2,
          halfHeight: (Math.abs(Math.sin(rad)) * itemWidth) / 2 + (Math.abs(Math.cos(rad)) * itemHeight) / 2,
        };
      };

      const isOffsetInsideContainer = (offset) => {
        const containerRect = container.getBoundingClientRect();
        const trackRect = track.getBoundingClientRect();

        const originX = trackRect.left + trackRect.width / 2;
        const originYTop = trackRect.top;

        const leftLimit = containerRect.left - originX;
        const rightLimit = containerRect.right - originX;
        const topLimit = containerRect.top - originYTop;
        const bottomLimit = containerRect.bottom - originYTop;

        const bounds = getBoundsAtAngle(offset * rotateStep);

        const cardLeft = bounds.x - bounds.halfWidth;
        const cardRight = bounds.x + bounds.halfWidth;
        const cardTop = bounds.y - bounds.halfHeight;
        const cardBottom = bounds.y + bounds.halfHeight;

        return cardRight >= leftLimit && cardLeft <= rightLimit && cardBottom >= topLimit && cardTop <= bottomLimit;
      };

      const getVisibleOffsets = () => {
        const offsets = [0];
        const maxSide = Math.ceil(maxLoopItems / 2);

        let leftEdge = 0;
        let rightEdge = 0;

        for (let i = 1; i <= maxSide; i++) {
          if (!isOffsetInsideContainer(i)) break;
          offsets.push(i);
          rightEdge = i;
        }

        for (let i = 1; i <= maxSide; i++) {
          if (!isOffsetInsideContainer(-i)) break;
          offsets.unshift(-i);
          leftEdge = -i;
        }

        const nextLeft = leftEdge - 1;
        const nextRight = rightEdge + 1;

        if (Math.abs(nextLeft) <= maxSide) offsets.unshift(nextLeft);
        if (Math.abs(nextRight) <= maxSide) offsets.push(nextRight);

        return offsets;
      };

      const visibleOffsets = getVisibleOffsets();
      const minItemsNeeded = Math.min(maxLoopItems, Math.max(originalItems.length, visibleOffsets.length));
      const neededItems = Math.ceil(minItemsNeeded / originalItems.length) * originalItems.length;

      for (let i = originalItems.length; i < neededItems; i++) {
        const clone = originalItems[i % originalItems.length].cloneNode(true);

        clone.setAttribute('data-radial-slider-clone', '');
        clone.setAttribute('aria-hidden', 'true');

        track.appendChild(clone);
      }

      const items = Array.from(track.querySelectorAll(':scope > [data-radial-slider-item]'));
      const totalItems = items.length;

      track.style.height = itemHeight + 'px';

      items.forEach((item) => {
        item.setAttribute('data-radial-slider-item-status', 'not-active');
      });

      container.setAttribute('data-radial-slider-drag-status', 'grab');

      const containerRect = container.getBoundingClientRect();
      const collectionRect = collection.getBoundingClientRect();
      const trackRect = track.getBoundingClientRect();

      const proxyWrap = document.createElement('div');
      proxyWrap.setAttribute('data-radial-slider-proxy-wrap', '');

      Object.assign(proxyWrap.style, {
        position: 'absolute',
        left: containerRect.left - collectionRect.left + 'px',
        top: containerRect.top - collectionRect.top + 'px',
        width: containerRect.width + 'px',
        height: containerRect.height + 'px',
        overflow: 'hidden',
        pointerEvents: 'none',
      });

      const proxy = document.createElement('div');
      proxy.setAttribute('data-radial-slider-proxy', '');

      Object.assign(proxy.style, {
        position: 'absolute',
        width: proxyRadius * 2 + 'px',
        height: proxyRadius * 2 + 'px',
        left: trackRect.left + trackRect.width / 2 - containerRect.left + 'px',
        top: trackRect.top - containerRect.top + originY - proxyRadius + 'px',
        transform: 'translateX(-50%)',
        borderRadius: '50%',
        pointerEvents: 'auto',
        opacity: '0',
      });

      proxyWrap.appendChild(proxy);
      collection.appendChild(proxyWrap);

      container._radialSliderProxy = proxy;
      container._radialSliderProxyEl = proxyWrap;

      const setRotation = items.map((item) => gsap.quickSetter(item, 'rotation', 'deg'));

      gsap.set(proxy, { rotation: 0 });

      const getIndexFromProxy = () => -gsap.getProperty(proxy, 'rotation') / rotateStep;

      const nearestDelta = (index, realIndex, total) => {
        const loop = Math.round((realIndex - index) / total);
        return index - (realIndex - loop * total);
      };

      const render = () => {
        const realIndex = getIndexFromProxy();
        const activeIndex = mod(Math.round(realIndex), totalItems);

        items.forEach((item, index) => {
          const rotation = nearestDelta(index, realIndex, totalItems) * rotateStep;

          item.setAttribute('data-radial-slider-item-status', index === activeIndex ? 'active' : 'inview');
          setRotation[index](rotation);
        });
      };

      container._radialSliderDraggable = Draggable.create(proxy, {
        type: 'rotation',
        trigger: [proxy, ...items],
        inertia: true,
        throwResistance: 2000,
        dragResistance: 0.05,
        maxDuration: 1,
        minDuration: 0.5,
        edgeResistance: 0.75,
        overshootTolerance: 0,
        snap: (value) => Math.round(value / rotateStep) * rotateStep,
        onDrag: render,
        onThrowUpdate: render,
        onThrowComplete: () => {
          container.setAttribute('data-radial-slider-drag-status', 'grab');
          render();
        },
        onPress: () => container.setAttribute('data-radial-slider-drag-status', 'grabbing'),
        onDragStart: () => container.setAttribute('data-radial-slider-drag-status', 'grabbing'),
        onRelease: () => container.setAttribute('data-radial-slider-drag-status', 'grab'),
      })[0];

      render();

      const autoplaySpeed = 2.5;
      const autoplayResumeDelay = 4;
      const autoplayRamp = 1.5;
      const speed = { value: 0 };

      const isUserActive = () => {
        const draggable = container._radialSliderDraggable;
        return draggable && (draggable.isPressed || draggable.isThrowing);
      };

      const tick = (time, deltaTime) => {
        if (!speed.value || !container._radialSliderInView || isUserActive()) return;

        const rotation = gsap.getProperty(proxy, 'rotation') - autoplaySpeed * speed.value * (deltaTime / 1000);
        gsap.set(proxy, { rotation });
        render();
      };

      const startAutoplay = () => {
        if (window.ihMotion.isPaused()) return;

        if (isUserActive()) {
          container._radialSliderAutoplay = gsap.delayedCall(autoplayResumeDelay, startAutoplay);
          return;
        }

        gsap.to(speed, { value: 1, duration: autoplayRamp, ease: 'power1.inOut', overwrite: true });
      };

      container._radialSliderPauseAutoplay = () => {
        if (window.ihMotion.isPaused()) return;

        gsap.killTweensOf(speed);
        speed.value = 0;

        if (container._radialSliderAutoplay) container._radialSliderAutoplay.kill();
        container._radialSliderAutoplay = gsap.delayedCall(autoplayResumeDelay, startAutoplay);
      };

      container._radialSliderSetMotion = (paused) => {
        if (container._radialSliderAutoplay) container._radialSliderAutoplay.kill();

        if (paused) {
          gsap.to(speed, { value: 0, duration: 0.6, ease: 'power1.out', overwrite: true });
        } else {
          startAutoplay();
        }
      };

      if (!container._radialSliderAutoplayBound) {
        container.addEventListener('pointerdown', () => container._radialSliderPauseAutoplay?.(), { capture: true });

        new IntersectionObserver((entries) => {
          container._radialSliderInView = entries[0].isIntersecting;
        }).observe(container);

        window.ihMotion.onChange((paused) => container._radialSliderSetMotion?.(paused));

        container._radialSliderAutoplayBound = true;
      }

      container._radialSliderTick = tick;
      gsap.ticker.add(tick);
      startAutoplay();
    });

    if (initRadialCardsSlider._resize) {
      window.removeEventListener('resize', initRadialCardsSlider._resize);
    }

    initRadialCardsSlider._resize = debounceOnWidthChange(initRadialCardsSlider, 200);
    window.addEventListener('resize', initRadialCardsSlider._resize);
  }

  function debounceOnWidthChange(fn, ms) {
    let lastWidth = window.innerWidth;
    let timer;

    return function (...args) {
      clearTimeout(timer);

      timer = setTimeout(() => {
        if (window.innerWidth === lastWidth) return;

        lastWidth = window.innerWidth;
        fn.apply(this, args);
      }, ms);
    };
  }

  document.addEventListener('DOMContentLoaded', () => {
    initRadialCardsSlider();
  });

document.addEventListener('DOMContentLoaded', () => {
    const isHoverDevice = window.matchMedia('(hover: hover) and (pointer: fine)').matches;

    document.querySelectorAll('[data-hover-video]').forEach((wrap) => {
      const video = wrap.querySelector('video');
      if (!video) return;

      video.muted = true;
      video.playsInline = true;

      const play = () => {
        video.play().catch(() => {});
        wrap.setAttribute('data-hover-video-status', 'playing');
      };

      const stop = () => {
        video.pause();
        video.currentTime = 0;
        wrap.setAttribute('data-hover-video-status', 'not-active');
      };

      stop();

      if (isHoverDevice) {
        wrap.addEventListener('mouseenter', play);
        wrap.addEventListener('mouseleave', stop);
        return;
      }

      let inView = false;
      const sync = () => (inView && !window.ihMotion.isPaused() ? play() : stop());

      new IntersectionObserver(
        (entries) => {
          inView = entries[0].isIntersecting;
          sync();
        },
        { rootMargin: '100px 0px' },
