function initDynamicTextCursor() {
    const cursor = document.querySelector('[data-cursor]');
    const cursorTextTarget = document.querySelector('[data-cursor-text-target]');

    if (!cursor || !window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;

    let mouseX = 0;
    let mouseY = 0;
    let hasMouseMoved = false;

    const xTo = gsap.quickTo(cursor, 'x', { duration: 0.4, ease: 'power3.out' });
    const yTo = gsap.quickTo(cursor, 'y', { duration: 0.4, ease: 'power3.out' });

    function updateCursor() {
      const hoverItem = document.elementFromPoint(mouseX, mouseY)?.closest('[data-cursor-hover]');
      const rect = cursor.getBoundingClientRect();

      const isHovering = !!hoverItem;
      const isEdge = rect.right >= window.innerWidth;

      cursor.setAttribute('data-cursor', isHovering ? (isEdge ? 'active-edge' : 'active') : '');

      if (hoverItem && cursorTextTarget) {
        const text = hoverItem.getAttribute('data-cursor-text');
        if (text) cursorTextTarget.textContent = text;
      }
    }

    window.addEventListener('mousemove', (event) => {
      mouseX = event.clientX;
      mouseY = event.clientY;
      hasMouseMoved = true;

      xTo(mouseX);
      yTo(mouseY);

      requestAnimationFrame(updateCursor);
    });

    window.addEventListener(
      'scroll',
      () => {
        if (!hasMouseMoved) return;
        requestAnimationFrame(updateCursor);
      },
      { passive: true },
    );
  }

  document.addEventListener('DOMContentLoaded', () => {
    initDynamicTextCursor();
  });

function initMomentumBasedHover() {
    if (!window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;

    const xyMultiplier = 24;
    const rotationMultiplier = 16;
    const inertiaResistance = 120;
    const velocitySmoothing = 0.35;
    const hoverScale = 1.03;

    const clampXY = gsap.utils.clamp(-900, 900);
    const clampRot = gsap.utils.clamp(-45, 45);

    document.querySelectorAll('[data-momentum-hover-init]').forEach((root) => {
      let prevX = null,
        prevY = null;
      let velX = 0,
        velY = 0;
      let rafId = null;
      let lastEvent = null;

      root.addEventListener('mousemove', (e) => {
        lastEvent = e;
        if (rafId) return;
        rafId = requestAnimationFrame(() => {
          if (prevX !== null) {
            const dx = lastEvent.clientX - prevX;
            const dy = lastEvent.clientY - prevY;
            velX += (dx - velX) * velocitySmoothing;
            velY += (dy - velY) * velocitySmoothing;
          }
          prevX = lastEvent.clientX;
          prevY = lastEvent.clientY;
          rafId = null;
        });
      });

      root.addEventListener('mouseleave', () => {
        prevX = prevY = null;
        velX = velY = 0;
      });

      root.querySelectorAll('[data-momentum-hover-element]').forEach((el) => {
        const target = el.querySelector('[data-momentum-hover-target]');
        if (!target) return;

        gsap.set(target, { force3D: true });

        el.addEventListener('mouseenter', (e) => {
          if (window.ihMotion.isPaused()) return;

          const { left, top, width, height } = target.getBoundingClientRect();
          const offsetX = e.clientX - (left + width / 2);
          const offsetY = e.clientY - (top + height / 2);

          const rawTorque = offsetX * velY - offsetY * velX;
          const leverDist = Math.hypot(offsetX, offsetY) || 1;
          const angularForce = rawTorque / leverDist;

          gsap.to(target, {
            inertia: {
              x: { velocity: clampXY(velX * xyMultiplier), end: 0 },
              y: { velocity: clampXY(velY * xyMultiplier), end: 0 },
              rotation: { velocity: clampRot(angularForce * rotationMultiplier), end: 0 },
              resistance: inertiaResistance,
            },
          });

          gsap.to(target, { scale: hoverScale, duration: 0.6, ease: 'power3.out', overwrite: 'auto' });
        });

        el.addEventListener('mouseleave', () => {
          gsap.to(target, { scale: 1, duration: 0.8, ease: 'power3.out', overwrite: 'auto' });
        });
      });
    });
  }

  document.addEventListener('DOMContentLoaded', () => {
    initMomentumBasedHover();
  });

