                         false, false, false, false, 0, null);
      $(this).get(0).dispatchEvent(evt);
    });

    // Toggle aria attributes on click
    accordionButtons.on('click', function(e) {
      $(this).toggleAttrVal('aria-expanded', "false", "true");
      $(this).parent().find('.accordion-content').toggleAttrVal('aria-hidden', "true", "false");
    });

    // Custom toggleAttrVal function
    $.fn.toggleAttrVal = function(attr, val1, val2) {
      var test = $(this).attr(attr);
      if (test === val1) {
        $(this).attr(attr, val2);
      } else if (test === val2) {
        $(this).attr(attr, val1);
      } else {
        $(this).attr(attr, val1);
      }
      return this;
    };
  });

$(document).ready(function() {
    /* ---------------------------
       Focus Trap + Keyboard Support
    ---------------------------- */
    var buttonThatOpenedModal;
    var findModal = function(elem) {
      var tabbable = elem.find('select, input, textarea, button, a').filter(':visible');
      var firstTabbable = tabbable.first();
      var lastTabbable = tabbable.last();
      firstTabbable.focus();

      lastTabbable.on('keydown', function(e) {
        if (e.which === 9 && !e.shiftKey) {
          e.preventDefault();
          firstTabbable.focus();
        }
      });
      firstTabbable.on('keydown', function(e) {
        if (e.which === 9 && e.shiftKey) {
          e.preventDefault();
          lastTabbable.focus();
        }
      });
      elem.on('keydown', function(e) {
        if (e.keyCode === 27) {
          $(elem).find('.modal-close_btn').click();
        }
      });
    };

    var modalOpenButton = $('.modal-open_btn');
    modalOpenButton.on('keydown', function(e) {
      if (e.which !== 13 && e.which !== 32) return;
      e.preventDefault();
      var evt = document.createEvent("MouseEvents");
      evt.initMouseEvent("click", true, true, window, 0,0,0,0,0,false,false,false,false,0,null);
      $(this).get(0).dispatchEvent(evt);
    });
    modalOpenButton.on('click', function() {
      $(this).next().show();
      findModal($(this).next());
      buttonThatOpenedModal = $(this);
    });

    var modalCloseButton = $('.modal-close_btn, .modal-close_area');
    modalCloseButton.on('keydown', function(e) {
      if (e.which !== 13 && e.which !== 32) return;
      e.preventDefault();
      var evt = document.createEvent("MouseEvents");
      evt.initMouseEvent("click", true, true, window, 0,0,0,0,0,false,false,false,false,0,null);
      $(this).get(0).dispatchEvent(evt);
    });
    modalCloseButton.on('click', function() {
      $(this).closest('.modal-wrapper').hide();
      if (buttonThatOpenedModal) {
        buttonThatOpenedModal.focus();
        buttonThatOpenedModal = null;
      }
    });

    /* ---------------------------
       Scroll Lock on open/close
    ---------------------------- */
    $('.modal-open_btn').click(function(e) {
      e.preventDefault();
      if (document.documentElement.clientWidth > 991) {
        $('body').css('margin-right', '15px');
      }
      $('body').css('overflow', 'hidden');
    });
    $('.modal-close_area, .modal-close_btn').click(function(e) {
      e.preventDefault();
      if (document.documentElement.clientWidth > 991) {
        $('body').css('margin-right', '0px');
      }
      $('body').css('overflow', 'auto');
    });

    /* ---------------------------
       Background Video Handling
    ---------------------------- */
    function initBackgroundVideoHandling() {
      const bgWrappers = $(".video-modal-trigger-bg-video");
      if (!bgWrappers.length) return;

      let userPaused = new WeakMap();

      // Track user pause/play when no modal is open
      bgWrappers.each(function() {
        const video = $(this).find("video").get(0);
        if (!video) return;
        $(video).on("pause", function () {
          if (!$(".modal-wrapper:visible").length) userPaused.set(video, true);
        });
        $(video).on("play", function () {
          if (!$(".modal-wrapper:visible").length) userPaused.set(video, false);
        });
      });

      // Pause background videos when any modal opens
      $(document).on("click", ".modal-open_btn", function() {
        bgWrappers.each(function() {
          const video = $(this).find("video").get(0);
          if (video && !video.paused) {
            video.pause();
          }
        });
      });

      // Resume background videos when all modals are closed
      $(document).on("click", ".modal-close_btn, .modal-close_area", function() {
        // Nur wenn kein Modal mehr sichtbar ist
        if (!$(".modal-wrapper:visible").length) {
          bgWrappers.each(function() {
            const video = $(this).find("video").get(0);
            if (video && video.paused && !userPaused.get(video)) {
              // leicht verzögert starten für smoothes Ausblenden
              setTimeout(() => video.play(), 400);
            }
          });
        }
      });
    }

    // Warte, bis Webflow Videos tatsächlich im DOM eingefügt hat.
    // Early-Return auf Seiten ohne Background-Video, plus Notbremse nach 10 s.
    function waitForWebflowVideos() {
      if (!document.querySelector('.video-modal-trigger-bg-video')) return;

      let attempts = 0;
      const check = setInterval(() => {
        if ($(".video-modal-trigger-bg-video video").length > 0) {
          clearInterval(check);
          initBackgroundVideoHandling();
        } else if (++attempts >= 50) {
          clearInterval(check);
        }
      }, 200);
    }
    waitForWebflowVideos();
  });

(function () {
  var wrappers = document.querySelectorAll('[data-bg-video]');
  if (!wrappers.length) return;

  function activate(video) {
    if (!video || video.dataset.bgVideoLoaded) return;
    var sources = video.querySelectorAll('source[data-src]');
    if (!sources.length) return;
    video.dataset.bgVideoLoaded = '1';
    Array.prototype.forEach.call(sources, function (s) {
      s.src = s.getAttribute('data-src');
      s.removeAttribute('data-src');
    });
    video.load();
  }

  function play(video) {
    activate(video);
    var p = video.play();
    // Autoplay kann blockiert sein – dann bleibt das Poster stehen.
    if (p && typeof p.catch === 'function') p.catch(function () {});
  }

  /* --- Play/Pause-Button --------------------------------------------
     ACHTUNG, die Klassennamen sind gegenüber den Glyphen invertiert.
     Sie beschreiben den Zustand des Videos, nicht das Symbol:
       .bg-video_control_play-state   enthält das PAUSE-Icon (alt="Pause video")
                                      -> sichtbar, WÄHREND das Video läuft
       .bg-video_control_pause-state  enthält das PLAY-Icon  (alt="Play video")
                                      -> sichtbar, WÄHREND das Video steht
     Sichtbarkeit über das hidden-Attribut, ausgewertet von
     .w-background-video--control > [hidden] { display:none !important }
     in webflow.css. Kein eigenes CSS nötig.                          */
  Array.prototype.forEach.call(wrappers, function (wrap, index) {
    var btn = wrap.querySelector('[data-w-bg-video-control]');
    var video = wrap.querySelector('video');
    if (!btn || !video) return;

    var whilePlaying = btn.querySelector('.bg-video_control_play-state');
    var whilePaused  = btn.querySelector('.bg-video_control_pause-state');

    // aria-controls zeigte auf die entfernte Webflow-ID – neu verknüpfen.
    if (!video.id) video.id = 'bg-video-' + (index + 1);
    btn.setAttribute('aria-controls', video.id);

    function sync() {
      var running = !video.paused;
      if (whilePlaying) whilePlaying.hidden = !running;
      if (whilePaused)  whilePaused.hidden  = running;
      btn.setAttribute('aria-label',
        running ? 'Hintergrundvideo pausieren' : 'Hintergrundvideo abspielen');
    }

    btn.addEventListener('click', function (e) {
      // WICHTIG: Webflow hat einen delegierten jQuery-Klick-Handler auf
      // document, der dieses Video sofort wieder startet. Ohne
      // stopPropagation() pausiert das Video und läuft im selben Klick
      // wieder an – der Button wirkt dann funktionslos.
      e.stopPropagation();
      if (video.paused) play(video); else video.pause();
    });

    video.addEventListener('play', sync);
    video.addEventListener('pause', sync);
    sync();
  });

  /* --- Lazy Loading -------------------------------------------------
     Reduced Motion: nicht automatisch laden. Der Button bleibt nutzbar,
     wer will, startet das Video selbst.                              */
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  if (!('IntersectionObserver' in window)) {
    Array.prototype.forEach.call(wrappers, function (w) {
      var v = w.querySelector('video');
      if (v) play(v);
    });
    return;
  }

  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      if (!entry.isIntersecting) return;
      io.unobserve(entry.target);
      var v = entry.target.querySelector('video');
      if (v) play(v);
    });
  }, { rootMargin: '200px 0px' });

  Array.prototype.forEach.call(wrappers, function (w) { io.observe(w); });
})();

$(document).ready(function () {
    $('.w-dropdown').each(function () {
      const dropdown   = this;
      const $dropdown  = $(dropdown);
      const toggle     = $dropdown.find('.w-dropdown-toggle')[0];
      const $toggle    = $(toggle);

      // All focusable elements inside this dropdown, incl. the toggle
      const focusableElements = $dropdown.find(
        'a, button, .w-dropdown-toggle, [tabindex]:not([tabindex="-1"])'
      );

      /* ---------- helpers ---------- */
      function triggerEnterKey (element) {
        element.dispatchEvent(
          new KeyboardEvent('keydown', {
            bubbles   : true,
            cancelable: true,
            key       : 'Enter',
            code      : 'Enter',
            keyCode   : 13,
            which     : 13
          })
        );
      }

      function closeDropdown () {
        if (toggle.classList.contains('w--open')) {
          triggerEnterKey(toggle);   // let Webflow do the closing
        }
      }

      /* ---------- TAB / Shift+TAB handling (unchanged) ---------- */
      // Forward tab out of the last dropdown link
      focusableElements.last().on('keydown', function (e) {
        if (e.key === 'Tab' && !e.shiftKey) {
          setTimeout(() => {
            if (!$dropdown.find(':focus').length) closeDropdown();
          }, 0);
        }
      });

      // Reverse tab out of the first dropdown link
      focusableElements.first().on('keydown', function (e) {
        if (e.key === 'Tab' &&  e.shiftKey) {
          setTimeout(() => {
            if (!$dropdown.find(':focus').length) closeDropdown();
          }, 0);
        }
      });

      // Reverse tab off the toggle itself
      $toggle.on('keydown', function (e) {
        if (e.key === 'Tab' &&  e.shiftKey) {
          setTimeout(() => {
            if (!$dropdown.find(':focus').length) closeDropdown();
          }, 0);
        }
      });

      /* ---------- NEW: screen-reader / arrow-key support ---------- */
      $dropdown.on('focusout', function () {
        // Wait for the next element to receive focus
        setTimeout(() => {
          if (!$dropdown.find(':focus').length) {
            closeDropdown();         // focus moved outside → close
          }
        }, 0);
      });
    });
  });

