		if (u == null) { return ''; }
		u = String(u);
		if (!u || /^(data|blob|javascript|about|mailto|tel|#):/i.test(u)) { return ''; }
		try { return new URL(u, w.location.href).href; } catch (e) { return ''; }
	}

	function hostOf(u) {
		var a = absUrl(u);
		if (!a) { return ''; }
		try { return new URL(a).hostname.toLowerCase(); } catch (e) { return ''; }
	}

