	}

	/* <?php element src interception ?> */
	function park(el, url, kind) {
		try {
			var host = hostOf(url);
			oSetAttr.call(el, 'data-dmm-src', String(url));
			oSetAttr.call(el, 'data-dmm-cat', catOf(host, absUrl(url)));
			if (kind === 'script') { oSetAttr.call(el, 'type', 'text/plain'); }
		} catch (e) { /* noop */ }
	}

	function guardSrc(proto, prop, kind) {
		if (!proto) { return; }
		var desc = Object.getOwnPropertyDescriptor(proto, prop);
		if (!desc || !desc.set) { return; }

		Object.defineProperty(proto, prop, {
			configurable: true,
