	function scrub(markup) {
		return String(markup).replace(
			/<script\b([^>]*?)\ssrc\s*=\s*(["'])(.*?)\2([^>]*)>/gi,
			function (all, pre, q, url, post2) {
				if (decide(url, 'docwrite')) { return all; }
				return '<script' + pre + ' type="text/plain" data-dmm-cat="' + catOf(hostOf(url), absUrl(url)) +
					'" data-dmm-src=' + q + url + q + post2 + '>';
			}
