	/* <?php grecaptcha stand-in while reCAPTCHA is parked ?> */
	// Integrations read window.grecaptcha once, when their own script runs, and keep that object:
	// Gravity Forms passes window.grecaptcha||{} into its closure. With api.js parked that is an
	// empty object, so ready() throws on page load and execute() throws on every submit — consent
	// or not, because a parked script is only released after DOMContentLoaded, well after the defer
	// script that captured the global. The stand-in is what they capture instead: it queues until
	// the real client exists, then forwards to it.
	//
	// It has to leave the global before api.js runs. The loader adopts whatever grecaptcha it finds
	// and keeps an existing ready(), which would leave the stand-in waiting on itself.
	var RC_LOADER  = /\/recaptcha\/(?:api|enterprise)\.js/i;
	var rcStub     = null;
	var rcQueue    = [];
	var rcTimer    = null;
	var rcReleased = false;

	function rcTarget(ent) {
		var g = w.grecaptcha;
		if (!g || g === rcStub) { return null; }
		var t = ent ? g.enterprise : g;
		return t && typeof t.ready === 'function' ? t : null;
	}

	// Only api.js having run is waited on here. The real ready() already holds a callback until
	// recaptcha__en.js has loaded and execute/render exist.
	function rcWhen(ent, fn) {
		rcQueue.push([ent, fn]);
		if (rcTimer) { return; }

		var tick = function () {
			var waiting = rcQueue;
			rcQueue = [];
			for (var i = 0; i < waiting.length; i++) {
				var t = rcTarget(waiting[i][0]);
				if (!t) { rcQueue.push(waiting[i]); continue; }
				t.ready((function (job, target) { return function () { job(target); }; }(waiting[i][1], t)));
			}
			if (!rcQueue.length) { w.clearInterval(rcTimer); rcTimer = null; }
		};

		rcTimer = w.setInterval(tick, 100);
		tick();
	}

	function rcDrop(url) {
		if (!rcStub || w.grecaptcha !== rcStub || !RC_LOADER.test(String(url || ''))) { return; }
		try { delete w.grecaptcha; } catch (e) { /* non-configurable */ }
