        const keys = input.split('.');
        const result = {};
        let current = result;
        for (let i = 0; i < keys.length - 1; i++) {
          const key = keys[i];
          if (key.endsWith("[]")) {
            const arrayKey = key.slice(0, -2);
            if (!current[arrayKey]) {
              current[arrayKey] = [];
            }
