document.addEventListener("DOMContentLoaded", function () {

  const dropdown = document.querySelector(".nav_dropdown");
  const dropdownToggle = document.querySelector(".nav_dropdown-toggle");
  const dropdownList = document.querySelector(".nav_drop-menu");

  if (dropdown && dropdownToggle && dropdownList) {
    dropdown.setAttribute("data-hover", "false");

    let isMenuOpen = false;
    let isAnimating = false;

    function toggleDropdown(state) {
      isMenuOpen = state;
      isAnimating = true;

      if (isMenuOpen) {
        dropdown.classList.add("is-dropdown-open", "w--open");
        dropdownToggle.classList.add("w--open");
        dropdownList.classList.add("is-dropdown-open", "w--open");
        dropdownToggle.setAttribute("aria-expanded", "true");
      } else {
        dropdown.classList.remove("is-dropdown-open", "w--open");
        dropdownToggle.classList.remove("w--open");
        dropdownList.classList.remove("is-dropdown-open", "w--open");
        dropdownToggle.setAttribute("aria-expanded", "false");
      }

      setTimeout(function () {
        isAnimating = false;
      }, 400);
    }

    dropdownToggle.addEventListener("mouseenter", function () {
      if (window.innerWidth <= 991 || isAnimating) return;
      toggleDropdown(!isMenuOpen);
    });

    document.addEventListener("click", function (e) {
      if (window.innerWidth <= 991 || !isMenuOpen) return;
      if (!dropdown.contains(e.target)) {
        toggleDropdown(false);
      }
    });
  }

  const navbarItems = document.querySelectorAll(".navbar_list .w-dyn-item");
  const contentItems = document.querySelectorAll(".nav_content-list .w-dyn-item");

  function normalizeUrl(url) {
    if (!url) return "";
    return new URL(url, window.location.origin).pathname.replace(/\/$/, "");
  }

  function getNavUrl(item) {
    const link = item.querySelector(".link");
    if (!link) return "";
    return normalizeUrl(link.getAttribute("href"));
  }

  function getContentUrl(item) {
    const link = item.querySelector(".nav_link_content-wrap .nav_impact_button");
    if (!link) return "";
    return normalizeUrl(link.getAttribute("href"));
  }

  function setActive(navItem) {
    const targetUrl = getNavUrl(navItem);
    if (!targetUrl) return;

    navbarItems.forEach(function (item) {
      item.classList.remove("is-active");
    });

    contentItems.forEach(function (item) {
      const content = item.querySelector(".nav_link_content-wrap , [navbar-image]");
      if (content) {
        content.classList.remove("is-active");
      }
    });

    navItem.classList.add("is-active");

    contentItems.forEach(function (item) {
      const contentUrl = getContentUrl(item);
      if (contentUrl === targetUrl) {
        const content = item.querySelector(".nav_link_content-wrap, [navbar-image]");
        if (content) {
          content.classList.add("is-active");
        }
      }
    });
  }

  const currentPath = normalizeUrl(window.location.pathname);
  let currentNavItem = null;

  navbarItems.forEach(function (item) {
    const navUrl = getNavUrl(item);
    if (navUrl === currentPath) {
      currentNavItem = item;
    }
  });

  if (currentNavItem) {
    setActive(currentNavItem);
  } else if (navbarItems.length) {
    setActive(navbarItems[0]);
  }

  navbarItems.forEach(function (item) {
    item.addEventListener("mouseenter", function () {
      setActive(item);
    });
  });

});

/* =========================================================
   KEEP THE ARROW ON THE HEADING'S LAST LINE

   DO NOT CHANGE
  ========================================================= */

  document.querySelectorAll('.hero_heading-wrap').forEach((wrap) => {
    const heading = wrap.querySelector('.heading-style-36');
    const icon = wrap.querySelector('.icon_span');

    if (!heading || !icon) return;
    if (heading.contains(icon)) return;

    const text = heading.textContent.replace(/\s+/g, ' ').trim();

    if (!text) return;

    const cut = text.lastIndexOf(' ');
    const head = cut === -1 ? '' : text.slice(0, cut + 1);
    const tail = cut === -1 ? text : text.slice(cut + 1);

    heading.textContent = head;

    const keep = document.createElement('span');

    keep.className = 'heading_nowrap';
    keep.textContent = tail;

    keep.appendChild(icon);

    heading.appendChild(keep);
  });

document.addEventListener('DOMContentLoaded', () => {
    /* =========================================================
     SETTINGS
    ========================================================= */

    const DESKTOP_TIME = 8;
    const MOBILE_TIME = 7;

    /* =========================================================
     ELEMENTS
    ========================================================= */

    const tabs = [...document.querySelectorAll('.auto-tab-link')];

    const mobileBars = [...document.querySelectorAll('.mobile-progress')];

    const mobileFills = [...document.querySelectorAll('.mobile-progress-fill')];

    const desktopProgress = document.querySelector('.desktop-progress-fill');

    if (!tabs.length) return;

    /* =========================================================
     BACKGROUND IMAGE SYSTEM
    ========================================================= */

    const hero = document.querySelector('.section_hero');

    const mainBg = hero ? hero.querySelector('.bg_img') : null;

    const heroItems = hero ? [...hero.querySelectorAll('.hero_items')] : [];

    let bgTransition = null;

    /* =========================================================
     CREATE BACKGROUND TRANSITION LAYER
    ========================================================= */

    if (mainBg && heroItems.length) {
      bgTransition = mainBg.cloneNode(true);

      bgTransition.classList.add('bg_img_transition');

      bgTransition.removeAttribute('id');

      bgTransition.style.opacity = '0';

      mainBg.parentNode.insertBefore(bgTransition, mainBg.nextSibling);

      mainBg.decoding = 'async';
      bgTransition.decoding = 'async';

      /* Keep both layers above .bg_img_next (same level as the
         transition layer), otherwise the empty placeholder covers it. */
      mainBg.style.zIndex = '0';
    }

    /* =========================================================
     TWO LAYERS THAT TAKE TURNS
     The layer that is showing is never given a new image.
     The new image always goes on the hidden layer, then the
     two swap roles.
    ========================================================= */

    let frontLayer = mainBg;
    let backLayer = bgTransition;
    let shownUrl = mainBg ? mainBg.currentSrc || mainBg.src : null;
    let bgRequest = 0;

    /* =========================================================
     GET CMS IMAGE
    ========================================================= */

    const getCMSImage = (index) => {
      const item = heroItems[index];

      if (!item) return null;

      const image = item.querySelector('.hero_cms_bg');

      if (!image) return null;

      return image.currentSrc || image.src || image.getAttribute('src');
    };

    /* =========================================================
     PRELOAD + DECODE IMAGE
     img.decode() decodes off the main thread, so the swap
     below does not freeze the page. One request per URL.
    ========================================================= */

    const preloadCache = new Map();

    const preloadImage = (url) => {
      if (!url) return Promise.resolve(false);

      if (preloadCache.has(url)) return preloadCache.get(url);

      const job = new Promise((resolve) => {
        const img = new Image();

        img.decoding = 'async';

        img.onload = () => {
          if (typeof img.decode === 'function') {
            img.decode().then(
              () => resolve(true),
              () => resolve(true),
            );
          } else {
            resolve(true);
          }
        };

        img.onerror = () => {
          resolve(false);
        };

        img.src = url;
      }).then((ok) => {
        if (!ok) preloadCache.delete(url);

        return ok;
      });

      preloadCache.set(url, job);

      return job;
    };

    /* =========================================================
     SET BACKGROUND IMAGE
    ========================================================= */

    const setBgImage = (element, url) => {
      if (!element || !url) return;

      if (element.tagName && element.tagName.toLowerCase() === 'img') {
        element.src = url;

        return;
      }

      element.style.backgroundImage = `url("${url}")`;
    };

    /* =========================================================
     CHANGE BACKGROUND
    ========================================================= */

    const changeBackground = async (index, immediate = false) => {
      if (!mainBg || !bgTransition) {
        return;
      }

      const newImage = getCMSImage(index);

      if (!newImage) return;

      const request = ++bgRequest;

      const loaded = await preloadImage(newImage);

      /* A newer tab change happened while this one was loading. */
      if (!loaded || request !== bgRequest) return;

      /* =======================================================
       INITIAL IMAGE
      ======================================================= */

      if (immediate) {
        gsap.killTweensOf([frontLayer, backLayer]);

        if (newImage !== shownUrl) {
          setBgImage(frontLayer, newImage);
        }

        gsap.set(frontLayer, {
          opacity: 1,
        });

        gsap.set(backLayer, {
          opacity: 0,
        });

        shownUrl = newImage;

        return;
      }

      if (newImage === shownUrl) return;

      /* =======================================================
       PUT NEW IMAGE ON THE HIDDEN LAYER
      ======================================================= */

      const incoming = backLayer;
      const outgoing = frontLayer;

      gsap.killTweensOf([incoming, outgoing]);

      gsap.set(incoming, {
        opacity: 0,
      });

      setBgImage(incoming, newImage);

      frontLayer = incoming;
      backLayer = outgoing;
      shownUrl = newImage;

      /* =======================================================
       CROSSFADE
      ======================================================= */

      const timeline = gsap.timeline();

      timeline.to(
        incoming,
        {
          opacity: 1,
          duration: 0.8,
          ease: 'power2.inOut',
        },
        0,
      );

      timeline.to(
        outgoing,
        {
          opacity: 0,
          duration: 0.8,
          ease: 'power2.inOut',
        },
        0,
      );
    };

    /* =========================================================
     RESPONSIVE
    ========================================================= */

    const isMobile = () => window.innerWidth <= 991;

    let currentIndex = 0;

    /* =========================================================
     ACTIVE TAB
    ========================================================= */

    const getActiveIndex = () => {
      const index = tabs.findIndex((tab) => tab.classList.contains('w--current'));

      return index >= 0 ? index : currentIndex;
    };

    const markActiveTab = (index) => {
      currentIndex = index;

      tabs.forEach((tab, i) => {
        tab.classList.toggle('w--current', i === index);
      });
    };

    /* Load + decode the next slide's image during the current slide. */
    const preloadNext = (index) => {
      preloadImage(getCMSImage((index + 1) % tabs.length));
    };

    const setActiveTab = (index) => {
      if (!tabs[index]) return;

      markActiveTab(index);

      changeBackground(index);

      preloadNext(index);
    };

    /* =========================================================
     MOBILE PROGRESS RESET
    ========================================================= */

    const resetMobileProgress = () => {
      gsap.killTweensOf(mobileBars);

      gsap.killTweensOf(mobileFills);

      gsap.set(mobileBars, {
        flex: 1,
      });

      gsap.set(mobileFills, {
        scaleX: 0,
        transformOrigin: 'left center',
      });
    };

    /* =========================================================
     START MOBILE PROGRESS
    ========================================================= */

    const startMobileTimer = (index) => {
      const bar = mobileBars[index];

      const fill = mobileFills[index];

      if (!bar || !fill) return;

      resetMobileProgress();

      gsap.to(bar, {
        flex: 4,
        duration: 0.35,
        ease: 'power2.out',
      });

      gsap.to(fill, {
        scaleX: 1,
        duration: MOBILE_TIME,
        ease: 'none',

        onComplete: () => {
          const nextIndex = (index + 1) % tabs.length;

          setActiveTab(nextIndex);

          startMobileTimer(nextIndex);
        },
      });
    };

    /* =========================================================
     START DESKTOP PROGRESS
    ========================================================= */

    const startDesktopTimer = (index) => {
      if (!desktopProgress) return;

      gsap.killTweensOf(desktopProgress);

      gsap.set(desktopProgress, {
        scaleX: 0,
        transformOrigin: 'left center',
      });

      gsap.to(desktopProgress, {
        scaleX: 1,
        duration: DESKTOP_TIME,
        ease: 'none',

        onComplete: () => {
          const nextIndex = (index + 1) % tabs.length;

          setActiveTab(nextIndex);

          startDesktopTimer(nextIndex);
        },
      });
    };

    /* =========================================================
     START CURRENT TAB
    ========================================================= */

    const startTabTimer = (index) => {
      if (isMobile()) {
        if (desktopProgress) {
          gsap.killTweensOf(desktopProgress);
        }

        startMobileTimer(index);
      } else {
        gsap.killTweensOf(mobileBars);

        gsap.killTweensOf(mobileFills);

        startDesktopTimer(index);
      }
    };

    /* =========================================================
     CLICK HANDLER
    ========================================================= */

    tabs.forEach((tab, index) => {
      tab.addEventListener('click', (event) => {
        const isAlreadyActive = tab.classList.contains('w--current');

        /* ===================================================
             ACTIVE TAB
          =================================================== */

        if (isAlreadyActive) {
          const heroItem = tab.closest('.hero_items');

          if (heroItem) {
            const pageLink = heroItem.querySelector('.external_stories-link_story');

            if (pageLink) {
              const url = pageLink.href || pageLink.getAttribute('href');

              if (url) {
                window.location.href = url;
              }
            }
          }

          return;
        }

        /* ===================================================
             INACTIVE TAB
          =================================================== */

        event.preventDefault();

        if (desktopProgress) {
          gsap.killTweensOf(desktopProgress);
        }

        gsap.killTweensOf(mobileBars);

        gsap.killTweensOf(mobileFills);

        setActiveTab(index);

        startTabTimer(index);
      });
    });

    /* =========================================================
     RESIZE
     Only restart when the layout switches between mobile and
     desktop. Height-only resizes (mobile address bar showing
     or hiding while scrolling) are ignored.
    ========================================================= */

    let resizeTimer;
    let lastWidth = window.innerWidth;
    let lastMobile = isMobile();

    window.addEventListener('resize', () => {
      clearTimeout(resizeTimer);

      resizeTimer = setTimeout(() => {
        if (window.innerWidth === lastWidth) return;

        lastWidth = window.innerWidth;

        const nowMobile = isMobile();

        if (nowMobile === lastMobile) return;

        lastMobile = nowMobile;

        startTabTimer(getActiveIndex());
      }, 250);
    });

    /* =========================================================
     INITIAL STATE
    ========================================================= */

    /* First image: show it straight away, no waiting for decode.
