document.addEventListener('DOMContentLoaded', () => {
    /* =========================================================
       UPDATE PREV / NEXT BUTTON OPACITY
    ========================================================= */

    function updateSliderButtonState(swiper) {
      const prevButton = swiper.navigation.prevEl;
      const nextButton = swiper.navigation.nextEl;

      if (!prevButton || !nextButton) return;

      // Number of REAL slides
      const totalSlides = swiper.pagination.bullets.length;

      // Current REAL slide index: 0, 1, 2...
      const currentIndex = swiper.realIndex;

      // First slide
      const isFirstSlide = currentIndex === 0;

      // Last slide
      const isLastSlide = currentIndex === totalSlides - 1;

      // Previous button
      prevButton.classList.toggle('is-disabled', isFirstSlide);

      // Next button
      nextButton.classList.toggle('is-disabled', isLastSlide);
    }

    /* =========================================================
       INITIALIZE ALL SLIDERS
    ========================================================= */

    document.querySelectorAll('.swiper.is-slider').forEach((slider) => {
      const swiper = new Swiper(slider, {
        /* =========================
           BASIC SETTINGS
        ========================= */

        slidesPerView: 1,

        loop: true,

        a11y: {
          enabled: false,
        },

        allowTouchMove: false,

        simulateTouch: false,

        grabCursor: false,

        autoplay: {
          delay: 6000,
          disableOnInteraction: false,
        },

        navigation: {
          nextEl: slider.parentElement.querySelector('.swiper-button-next'),

          prevEl: slider.parentElement.querySelector('.swiper-button-prev'),
        },

        pagination: {
          el: slider.parentElement.querySelector('.swiper-pagination'),

          clickable: true,

          renderBullet(index, className) {
            return `
              <button
                type="button"
                class="${className} swiper-pagination-is-slider-bullet"
                aria-label="Go to slide ${index + 1}"
              ></button>
            `;
          },
        },

        observer: true,

        observeParents: true,

        watchOverflow: true,

        on: {
          init(swiper) {
            /* -----------------------------------------
               Restart first bullet animation
            ----------------------------------------- */

            requestAnimationFrame(() => {
              const active = swiper.pagination.bullets[swiper.realIndex];

              if (!active) return;

              active.classList.remove('swiper-pagination-bullet-active');

              /* Force browser reflow */

              void active.offsetWidth;

              active.classList.add('swiper-pagination-bullet-active');
            });

            updateSliderButtonState(swiper);
          },

          slideChange(swiper) {
            updateSliderButtonState(swiper);
          },
        },
      });
    });
  });

