window.addEventListener('load', function () {
    const priorityTags = {
      Ambassadors: 1,
      Grantees: 2,
      Sponsorships: 3,
      Films: 4,
    };

    function processNavbarTags() {
      const targets = document.querySelectorAll('.feature_stories-list [fs-list-element="nest-target"][fs-list-nest="tags"]');

      targets.forEach(function (wrap) {
        const limit = parseInt(wrap.getAttribute('data-tag-limit'), 10) || 1;

        const list = wrap.querySelector('.nested_items');

        if (!list) return;

        const items = Array.from(list.children);

        if (!items.length) return;

        /*
         * Sort tags according to priority
         */
        items.sort(function (a, b) {
          const tagA = a.querySelector('.tagline')?.textContent.trim() || '';

          const tagB = b.querySelector('.tagline')?.textContent.trim() || '';

          const priorityA = priorityTags[tagA] ?? 999;

          const priorityB = priorityTags[tagB] ?? 999;

          return priorityA - priorityB;
        });

        /*
         * Reorder the actual tag items
         */
        items.forEach(function (item) {
          list.appendChild(item);
        });

        /*
         * Show only the requested number
         */
        items.forEach(function (item, index) {
          if (index < limit) {
            item.style.display = '';
          } else {
            item.style.display = 'none';
          }
        });
      });
    }

    /*
     * List Nest loads asynchronously.
     * Check only the navbar targets, not the entire body.
     */
    let attempts = 0;

    const checker = setInterval(function () {
      processNavbarTags();

      attempts++;

      if (attempts >= 50) {
        clearInterval(checker);
      }
    }, 100);
  });

(function () {
    function setCMSColors() {
      document.querySelectorAll('[data-cms-color-item]').forEach(function (item) {
        /* =========================================
         GET CMS COLOR
      ========================================= */

        const colorElement = item.querySelector('[data-cms-color]');

        if (!colorElement) return;

        const cmsColor = colorElement.style.color.trim();

        if (!cmsColor) return;

        /* =========================================
         STORE CMS COLOR
      ========================================= */

        item.style.setProperty('--cms-hover-color', cmsColor);

        /* =========================================
         BACKGROUND COLOR ELEMENTS
      ========================================= */

        item.querySelectorAll('[data-cms-color-bg]').forEach(function (element) {
          element.style.setProperty('background-color', cmsColor, 'important');
        });

        /* =========================================
         ARROW COLOR / LIGHT-DARK DETECTION
      ========================================= */

        item.querySelectorAll('[data-cms-color-arrow]').forEach(function (arrow) {
          const temp = document.createElement('div');

          temp.style.color = cmsColor;

          document.body.appendChild(temp);

          const rgb = getComputedStyle(temp).color;

          temp.remove();

          const match = rgb.match(/\d+/g);

          if (!match || match.length < 3) return;

          const r = Number(match[0]);
          const g = Number(match[1]);
          const b = Number(match[2]);

          const brightness = (r * 299 + g * 587 + b * 114) / 1000;

          arrow.classList.remove('cms-light-color', 'cms-dark-color');

          if (brightness > 155) {
            arrow.classList.add('cms-light-color');
          } else {
            arrow.classList.add('cms-dark-color');
          }
        });
      });
    }

    /* =========================================
     INITIALIZE
  ========================================= */

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', setCMSColors);
    } else {
      setCMSColors();
    }

    window.addEventListener('load', setCMSColors);
  })();

