document.addEventListener('DOMContentLoaded', function () {
    var tabs = Array.prototype.slice.call(document.querySelectorAll('.auto-tab-link'));
    var bars = Array.prototype.slice.call(document.querySelectorAll('.mobile-progress'));
    var area = document.querySelector('.section_hero');

    if (tabs.length < 2 || !area) return;

    function isMobile() {
      return window.innerWidth <= 991;
    }

    function activeIndex() {
      for (var i = 0; i < tabs.length; i++) {
        if (tabs[i].classList.contains('w--current')) return i;
      }
      return 0;
    }

    /* Clicking an inactive tab runs the existing hero code:
       switches tab, fades background, restarts progress. */
    var internalClick = false;

    function goTo(index) {
      var n = tabs.length;
      var i = ((index % n) + n) % n;
      if (i === activeIndex()) return;
      internalClick = true;
      tabs[i].click();
      internalClick = false;
    }

    /* Tap a progress bar */
    bars.forEach(function (bar, i) {
      bar.addEventListener('click', function (e) {
        if (!isMobile()) return;
        e.preventDefault();
        e.stopPropagation();
        goTo(i);
      });
    });

    /* Swipe left / right on the hero */
    var startX = 0;
    var startY = 0;
    var tracking = false;
    var swipedAt = 0;

    area.addEventListener('touchstart', function (e) {
      if (!isMobile() || e.touches.length !== 1) return;
      tracking = true;
      startX = e.touches[0].clientX;
      startY = e.touches[0].clientY;
    }, { passive: true });

    area.addEventListener('touchend', function (e) {
      if (!tracking) return;
      tracking = false;

      var t = e.changedTouches[0];
      var dx = t.clientX - startX;
      var dy = t.clientY - startY;

      /* Mostly horizontal and long enough = swipe */
      if (Math.abs(dx) < 40 || Math.abs(dx) < Math.abs(dy) * 1.5) return;

      goTo(activeIndex() + (dx < 0 ? 1 : -1));

      swipedAt = Date.now();
    }, { passive: true });

    area.addEventListener('touchcancel', function () {
      tracking = false;
    }, { passive: true });

    /* Stop the tap that follows a swipe from opening the story link */
    area.addEventListener('click', function (e) {
      if (internalClick) return;
      if (Date.now() - swipedAt < 400) {
        e.preventDefault();
        e.stopPropagation();
      }
    }, true);
  });

