    return isAnyDropdownOpen() || isMobileMenuOpen();
  }

  function lockScroll() {
    if (isLocked) return;

    isLocked = true;
    scrollPosition = window.scrollY;

    html.classList.add("nav-scroll-locked");
    body.classList.add("nav-scroll-locked");

    body.style.position = "fixed";
    body.style.top = "-" + scrollPosition + "px";
    body.style.left = "0";
    body.style.right = "0";
    body.style.width = "100%";
    body.style.overflow = "hidden";
  }

  function unlockScroll() {
    if (!isLocked) return;

    isLocked = false;

    html.classList.remove("nav-scroll-locked");
    body.classList.remove("nav-scroll-locked");

    Object.keys(originalStyles).forEach(function (property) {
      body.style[property] = originalStyles[property];
    });

