    function isMobile() {
      return window.innerWidth <= 991;
    }

    /* ==================================================
       MENU STILL VISIBLE?
       Webflow keeps data-nav-menu-open + overlay visible
       until the close animation finishes.
       ================================================== */

        function isMenuVisible() {
      return (
        menuButton.getAttribute('aria-expanded') === 'true' ||
        (navMenu && navMenu.hasAttribute('data-nav-menu-open')) ||
        menuButton.classList.contains('w--open')
      );
    }

    /* ==================================================
       UPDATE MOBILE MENU STATE
       ================================================== */

    function updateMobileMenu() {
      /*
       * NEVER affect desktop.
       */

      if (!isMobile()) {
        navComponent.classList.remove('mobile-menu-open');
        return;
      }

      navComponent.classList.toggle('mobile-menu-open', isMenuVisible());
