document.addEventListener("DOMContentLoaded", function () {

  const dropdown = document.querySelector(".nav_dropdown");
  const dropdownToggle = document.querySelector(".nav_dropdown-toggle");
  const dropdownList = document.querySelector(".nav_drop-menu");

  if (dropdown && dropdownToggle && dropdownList) {
    dropdown.setAttribute("data-hover", "false");

    let isMenuOpen = false;
    let isAnimating = false;

    function toggleDropdown(state) {
      isMenuOpen = state;
      isAnimating = true;

      if (isMenuOpen) {
        dropdown.classList.add("is-dropdown-open", "w--open");
        dropdownToggle.classList.add("w--open");
        dropdownList.classList.add("is-dropdown-open", "w--open");
        dropdownToggle.setAttribute("aria-expanded", "true");
      } else {
        dropdown.classList.remove("is-dropdown-open", "w--open");
        dropdownToggle.classList.remove("w--open");
        dropdownList.classList.remove("is-dropdown-open", "w--open");
        dropdownToggle.setAttribute("aria-expanded", "false");
      }

      setTimeout(function () {
        isAnimating = false;
      }, 400);
    }

    dropdownToggle.addEventListener("mouseenter", function () {
      if (window.innerWidth <= 991 || isAnimating) return;
      toggleDropdown(!isMenuOpen);
    });

    document.addEventListener("click", function (e) {
      if (window.innerWidth <= 991 || !isMenuOpen) return;
      if (!dropdown.contains(e.target)) {
        toggleDropdown(false);
      }
    });
  }

  const navbarItems = document.querySelectorAll(".navbar_list .w-dyn-item");
  const contentItems = document.querySelectorAll(".nav_content-list .w-dyn-item");

  function normalizeUrl(url) {
    if (!url) return "";
    return new URL(url, window.location.origin).pathname.replace(/\/$/, "");
  }

  function getNavUrl(item) {
    const link = item.querySelector(".link");
    if (!link) return "";
    return normalizeUrl(link.getAttribute("href"));
  }

  function getContentUrl(item) {
    const link = item.querySelector(".nav_link_content-wrap .nav_impact_button");
    if (!link) return "";
    return normalizeUrl(link.getAttribute("href"));
  }

  function setActive(navItem) {
    const targetUrl = getNavUrl(navItem);
    if (!targetUrl) return;

    navbarItems.forEach(function (item) {
      item.classList.remove("is-active");
    });

    contentItems.forEach(function (item) {
      const content = item.querySelector(".nav_link_content-wrap , [navbar-image]");
      if (content) {
        content.classList.remove("is-active");
      }
    });

    navItem.classList.add("is-active");

    contentItems.forEach(function (item) {
      const contentUrl = getContentUrl(item);
      if (contentUrl === targetUrl) {
        const content = item.querySelector(".nav_link_content-wrap, [navbar-image]");
        if (content) {
          content.classList.add("is-active");
        }
      }
    });
  }

  const currentPath = normalizeUrl(window.location.pathname);
  let currentNavItem = null;

  navbarItems.forEach(function (item) {
    const navUrl = getNavUrl(item);
    if (navUrl === currentPath) {
      currentNavItem = item;
    }
  });

  if (currentNavItem) {
    setActive(currentNavItem);
  } else if (navbarItems.length) {
    setActive(navbarItems[0]);
  }

  navbarItems.forEach(function (item) {
    item.addEventListener("mouseenter", function () {
      setActive(item);
    });
  });

});

