/* ==================================================
     MOBILE MENU STATE

     ONLY adds/removes:
     .mobile-menu-open

     OPEN  = instant on tap
     CLOSE = only after Webflow close animation ends

     DOES NOT modify desktop behavior.
     ================================================== */

  document.addEventListener('DOMContentLoaded', function () {
    const nav = document.querySelector('.nav_fixed');

    if (!nav) return;

    const navComponent = nav.querySelector('.nav_component');
    const menuButton = nav.querySelector('.menu-button');
    const navMenu = nav.querySelector('.w-nav-menu');

    if (!navComponent || !menuButton) return;

    /* ==================================================
       MOBILE CHECK
       ================================================== */

    function isMobile() {
      return window.innerWidth <= 991;
    }

    /* ==================================================
       MENU STILL VISIBLE?
       Webflow keeps data-nav-menu-open + overlay visible
       until the close animation finishes.
       ================================================== */

        function isMenuVisible() {
      return (
        menuButton.getAttribute('aria-expanded') === 'true' ||
        (navMenu && navMenu.hasAttribute('data-nav-menu-open')) ||
        menuButton.classList.contains('w--open')
      );
    }

    /* ==================================================
       UPDATE MOBILE MENU STATE
       ================================================== */

    function updateMobileMenu() {
      /*
       * NEVER affect desktop.
       */

      if (!isMobile()) {
        navComponent.classList.remove('mobile-menu-open');
        return;
      }

      navComponent.classList.toggle('mobile-menu-open', isMenuVisible());
    }

    /* ==================================================
