       ================================================== */

    const observer = new MutationObserver(function () {
      updateMobileMenu();
    });

    observer.observe(menuButton, {
      attributes: true,
      attributeFilter: ['aria-expanded'],
    });

    if (navMenu) {
      observer.observe(navMenu, {
        attributes: true,
        attributeFilter: ['data-nav-menu-open', 'style'],
      });
    }

    /* ==================================================
       INSTANT WHITE ON OPEN TAP
       Capture phase runs before Webflow opens the menu.
       Close is left to the observer (waits for animation).
       ================================================== */

    menuButton.addEventListener('click', function () {
      if (isMobile() && menuButton.getAttribute('aria-expanded') !== 'true') {
        navComponent.classList.add('mobile-menu-open');
      }
    }, true);

    /* ==================================================
       INITIAL STATE
       ================================================== */

    updateMobileMenu();

    /* ==================================================
       RESIZE
       ================================================== */

    window.addEventListener('resize', function () {
      if (!isMobile()) {
        navComponent.classList.remove('mobile-menu-open');
