      } else {
        nav.style.backgroundColor = 'transparent';

        nav.classList.remove('nav-scrolled');

        if (isStillWhite) {
          nav.classList.add('nav-text-dark');
        }
      }

      updateLogo();
    };

    /* ==================================================
       WATCH DROPDOWN FOR LOGO
       ================================================== */

    const navComponent = nav.querySelector('.nav_component');

    const dropdownToggle = nav.querySelector('.nav_dropdown-toggle');

    if (navComponent && dropdownToggle) {
      const dropdownObserver = new MutationObserver(function () {
        requestAnimationFrame(function () {
          updateLogo();
        });
      });

      dropdownObserver.observe(dropdownToggle, {
        attributes: true,
        attributeFilter: ['aria-expanded'],
      });
    }

    /* ==================================================
       LISTEN FOR SCROLL
       ================================================== */

    window.addEventListener('scroll', handleScroll);

    /* ==================================================
       INITIAL STATE
       ================================================== */

    handleScroll();
