document.addEventListener("DOMContentLoaded", function () {
  const dropdowns = document.querySelectorAll(".nav_dropdown");
  const menuButton = document.querySelector(".menu-button");
  const navComponent = document.querySelector(".nav_component");

  if (!dropdowns.length && !menuButton) return;

  let scrollPosition = 0;
  let isLocked = false;

  const body = document.body;
  const html = document.documentElement;

  // Preserve existing inline body styles
  const originalStyles = {
    position: body.style.position,
    top: body.style.top,
    left: body.style.left,
    right: body.style.right,
    width: body.style.width,
    overflow: body.style.overflow
  };

  function isMobile() {
    return window.innerWidth <= 991;
  }

  function isAnyDropdownOpen() {
    return Array.from(dropdowns).some(function (dropdown) {
      const toggle = dropdown.querySelector(".nav_dropdown-toggle");
      const menu = dropdown.querySelector(".nav_drop-menu");

      return (
        dropdown.classList.contains("w--open") ||
        (toggle && toggle.getAttribute("aria-expanded") === "true") ||
        (menu && menu.classList.contains("w--open"))
      );
    });
  }

  function isMobileMenuOpen() {
    if (!isMobile() || !menuButton) return false;

    return (
      menuButton.getAttribute("aria-expanded") === "true" ||
      menuButton.classList.contains("w--open") ||
      (navComponent && navComponent.classList.contains("mobile-menu-open"))
    );
  }

  function shouldLockScroll() {
    return isAnyDropdownOpen() || isMobileMenuOpen();
  }

  function lockScroll() {
    if (isLocked) return;

    isLocked = true;
    scrollPosition = window.scrollY;

    html.classList.add("nav-scroll-locked");
    body.classList.add("nav-scroll-locked");

    body.style.position = "fixed";
    body.style.top = "-" + scrollPosition + "px";
    body.style.left = "0";
    body.style.right = "0";
    body.style.width = "100%";
    body.style.overflow = "hidden";
  }

  function unlockScroll() {
    if (!isLocked) return;

    isLocked = false;

    html.classList.remove("nav-scroll-locked");
    body.classList.remove("nav-scroll-locked");

    Object.keys(originalStyles).forEach(function (property) {
      body.style[property] = originalStyles[property];
    });

    window.scrollTo(0, scrollPosition);
  }

  function updateScrollLock() {
    if (shouldLockScroll()) {
      lockScroll();
    } else {
      unlockScroll();
    }
  }

  // Observe the dropdown, its toggle and its menu
  const observer = new MutationObserver(updateScrollLock);

  dropdowns.forEach(function (dropdown) {
    [dropdown,
     dropdown.querySelector(".nav_dropdown-toggle"),
     dropdown.querySelector(".nav_drop-menu")
    ].filter(Boolean).forEach(function (element) {
      observer.observe(element, {
        attributes: true,
        attributeFilter: ["class", "aria-expanded"]
      });
    });
  });

  // Observe hamburger / mobile menu open state
  if (menuButton) {
    observer.observe(menuButton, {
      attributes: true,
      attributeFilter: ["class", "aria-expanded"]
    });
  }

  if (navComponent) {
    observer.observe(navComponent, {
      attributes: true,
      attributeFilter: ["class"]
    });
  }

  // Also handle mouse, keyboard and touch interactions
  document.addEventListener("click", function () {
    requestAnimationFrame(updateScrollLock);
  });

  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape") {
      setTimeout(updateScrollLock, 0);
    }
  });

  window.addEventListener("resize", function () {
    updateScrollLock();
  });

  updateScrollLock();
});

