document.addEventListener('DOMContentLoaded', function () {
    /* =========================================
     TAG PRIORITY
  ========================================= */

    const priorityTags = {
      Ambassadors: 1,
      Grantees: 2,
      Sponsorships: 3,
      Films: 4,
    };

    /*
     * Apply tag priority to every CMS card.
     *
     * IMPORTANT:
     * We HIDE lower-priority tags instead of removing them.
     * This keeps the CMS/List.js DOM intact.
     */
    function applyTagPriority() {
      const tagWrappers = document.querySelectorAll('.tag_cms.is-story-card-tags .tags-flex, .is-single-tag .tags-flex');

      tagWrappers.forEach(function (wrap) {
        const items = Array.from(wrap.children);

        if (!items.length) {
          return;
        }

        let bestItem = null;
        let bestPriority = Infinity;

        /*
         * Find the highest-priority tag.
         */
        items.forEach(function (item) {
          const tagline = item.querySelector('.tagline');

          if (!tagline) {
            return;
          }

          const tagName = tagline.textContent.trim();

          const priority = priorityTags[tagName] !== undefined ? priorityTags[tagName] : 999;

          if (priority < bestPriority) {
            bestPriority = priority;
            bestItem = item;
          }
        });

        /*
         * Hide every tag first.
         */
        items.forEach(function (item) {
          item.style.display = 'none';
        });

        /*
         * Show only the highest-priority tag.
         */
        if (bestItem) {
          bestItem.style.display = '';
        }
      });
    }

    /* =========================================
     PAGINATION
  ========================================= */

    const listWrapperEl = document.querySelector('[tw-list-pagination="wrapper"]');

    if (!listWrapperEl) {
      console.error('[tw-list-pagination] No element with tw-list-pagination="wrapper" found.');

      return;
    }

    const listItemsEl = listWrapperEl.querySelector('[tw-list-pagination="items"]');

    if (!listItemsEl) {
      console.error('[tw-list-pagination] No element with tw-list-pagination="items" found.');

      return;
    }

    const LIST_JS_HOOK_CLASS = 'tw-list-pagination-items';

    listItemsEl.classList.add(LIST_JS_HOOK_CLASS);

    const DEFAULT_MOBILE_PAGE_SIZE = 3;
    const DEFAULT_TABLET_PAGE_SIZE = 6;
    const DEFAULT_DESKTOP_PAGE_SIZE = 6;

    const TABLET_BREAKPOINT = 768;
    const DESKTOP_BREAKPOINT = 992;

    function readPageSizeAttr(attrName, fallback) {
      const raw = listItemsEl.getAttribute(attrName);

      const parsed = parseInt(raw, 10);

      return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
    }

    const MOBILE_PAGE_SIZE = readPageSizeAttr('tw-list-pagination-mobile', DEFAULT_MOBILE_PAGE_SIZE);

    const TABLET_PAGE_SIZE = readPageSizeAttr('tw-list-pagination-tab', DEFAULT_TABLET_PAGE_SIZE);

    const DESKTOP_PAGE_SIZE = readPageSizeAttr('tw-list-pagination-desktop', DEFAULT_DESKTOP_PAGE_SIZE);

    const collabList = new List(listWrapperEl, {
      listClass: LIST_JS_HOOK_CLASS,

      valueNames: ['title'],

      page: MOBILE_PAGE_SIZE,
    });

    /* =========================================
     VIEWPORT
  ========================================= */

    function getViewportTier() {
      const width = window.innerWidth;

      if (width >= DESKTOP_BREAKPOINT) {
        return 'desktop';
      }

      if (width >= TABLET_BREAKPOINT) {
        return 'tablet';
      }

      return 'mobile';
    }

    function pageSizeForViewport() {
      const tier = getViewportTier();

      if (tier === 'desktop') {
        return DESKTOP_PAGE_SIZE;
      }

      if (tier === 'tablet') {
        return TABLET_PAGE_SIZE;
      }

      return MOBILE_PAGE_SIZE;
    }

    /* =========================================
     PAGINATION ELEMENTS
  ========================================= */

    const pagerControlsEl = document.querySelector('[tw-list-pagination="controls"]');

    const pagerPrevButtonEl = document.querySelector('[tw-list-pagination="prev"]');

    const pagerNextButtonEl = document.querySelector('[tw-list-pagination="next"]');

    const pagerTrackEl = document.querySelector('[tw-list-pagination="track"]');

    const pagerSectionEl = document.querySelector('[tw-list-pagination="section"]');

    /* =========================================
     PAGE CALCULATIONS
  ========================================= */

    function getCurrentPage() {
      return Math.ceil(collabList.i / collabList.page);
    }

    function getTotalPages() {
      return Math.max(1, Math.ceil(collabList.size() / collabList.page));
    }

    /* =========================================
     PAGINATION DASHES
  ========================================= */

    function renderPagerDashes() {
      const totalPages = getTotalPages();

      const currentPage = getCurrentPage();

      if (!pagerTrackEl) {
        return;
      }

      pagerTrackEl.innerHTML = '';

      for (let pageNum = 1; pageNum <= totalPages; pageNum++) {
        const dashEl = document.createElement('button');

        dashEl.type = 'button';

        dashEl.className = 'pager-dash' + (pageNum === currentPage ? ' active' : '');

        dashEl.setAttribute('aria-label', 'Go to page ' + pageNum);

        dashEl.setAttribute('aria-current', pageNum === currentPage ? 'true' : 'false');

        dashEl.addEventListener('click', function () {
          goToPage(pageNum, {
            scrollToSection: true,
          });
        });

        pagerTrackEl.appendChild(dashEl);
      }
    }

    /* =========================================
     PAGINATION CONTROLS
  ========================================= */

    function renderPagerControls() {
      const totalPages = getTotalPages();

      if (pagerControlsEl) {
        pagerControlsEl.hidden = totalPages <= 1;
      }

      if (totalPages <= 1) {
        applyTagPriority();

        return;
      }

      const currentPage = getCurrentPage();

      if (pagerPrevButtonEl) {
        pagerPrevButtonEl.disabled = currentPage <= 1;
      }

      if (pagerNextButtonEl) {
        pagerNextButtonEl.disabled = currentPage >= totalPages;
      }

      renderPagerDashes();

      /*
       * List.js has changed the visible cards.
       * Reapply the tag priority.
       */
      requestAnimationFrame(function () {
        applyTagPriority();
      });
    }

    /* =========================================
     CARD FADE
  ========================================= */

    const CARD_SELECTOR = '[tw-list-pagination="item"]';

    const CARD_FADE_MS = 200;

    const CARD_STAGGER_MS = 20;

    function getVisibleCards() {
      return Array.prototype.filter.call(
        listItemsEl.querySelectorAll(CARD_SELECTOR),

        function (cardEl) {
          return cardEl.style.display !== 'none';
        },
      );
    }

    const CARD_OFFSET_PX = 5;

    function cardTransition(index) {
      const delay = index * CARD_STAGGER_MS + 'ms';

      return 'opacity ' + CARD_FADE_MS + 'ms ease ' + delay + ', transform ' + CARD_FADE_MS + 'ms ease ' + delay;
    }

    function fadeOutCards(cards, callback) {
      if (!cards.length) {
        callback();

        return;
      }

      cards.forEach(function (cardEl, index) {
        cardEl.style.transition = cardTransition(index);

        cardEl.style.opacity = '0';

        cardEl.style.transform = 'translateY(' + CARD_OFFSET_PX + 'px)';
      });

      const totalMs = CARD_FADE_MS + (cards.length - 1) * CARD_STAGGER_MS;

      window.setTimeout(callback, totalMs);
    }

    function hideCardsBeforeFadeIn(cards) {
      cards.forEach(function (cardEl) {
        cardEl.style.transition = 'none';

        cardEl.style.opacity = '0';

        cardEl.style.transform = 'translateY(' + CARD_OFFSET_PX + 'px)';
      });

      /*
       * Force reflow.
       */
      void listItemsEl.offsetHeight;
    }

    function revealCards(cards) {
      cards.forEach(function (cardEl, index) {
        cardEl.style.transition = cardTransition(index);

        cardEl.style.opacity = '1';

        cardEl.style.transform = 'translateY(0)';
      });
    }

    /* =========================================
     WAIT FOR SCROLL TO SETTLE
  ========================================= */

    const SCROLL_END_STABLE_FRAMES = 3;

    const SCROLL_END_MAX_WAIT_MS = 1200;

    function waitForScrollEnd(callback) {
      let lastScrollY = window.scrollY;

      let stableFrames = 0;

      const startTime = performance.now();

      function check() {
        const currentScrollY = window.scrollY;

        if (currentScrollY === lastScrollY) {
          stableFrames++;
        } else {
          stableFrames = 0;

          lastScrollY = currentScrollY;
        }

        const timedOut = performance.now() - startTime > SCROLL_END_MAX_WAIT_MS;

        if (stableFrames >= SCROLL_END_STABLE_FRAMES || timedOut) {
          callback();

          return;
        }

        requestAnimationFrame(check);
      }

      requestAnimationFrame(check);
    }

    /* =========================================
     GO TO PAGE
  ========================================= */

    let isFirstPageRender = true;

    function goToPage(targetPage, options) {
      const pageSize = collabList.page;

      const totalPages = getTotalPages();

      const clampedPage = Math.min(Math.max(targetPage, 1), totalPages);

      function applyPage() {
        collabList.show((clampedPage - 1) * pageSize + 1, pageSize);

        renderPagerControls();

        /*
         * Reapply tag priority after
         * List.js changes the cards.
         */
        requestAnimationFrame(function () {
          applyTagPriority();
        });

        const newCards = getVisibleCards();

        hideCardsBeforeFadeIn(newCards);

        revealCards(newCards);
      }

      if (isFirstPageRender) {
        isFirstPageRender = false;

        applyPage();

        return;
      }

      const shouldScroll = Boolean(options && options.scrollToSection && pagerSectionEl);

      const pendingTaskCount = shouldScroll ? 2 : 1;

      let finishedTaskCount = 0;

      function taskFinished() {
        finishedTaskCount++;

        if (finishedTaskCount >= pendingTaskCount) {
          applyPage();
        }
      }

      fadeOutCards(getVisibleCards(), taskFinished);

      if (shouldScroll) {
        pagerSectionEl.scrollIntoView({
          behavior: 'smooth',

          block: 'start',
        });

        waitForScrollEnd(taskFinished);
      }
    }

    /* =========================================
     PREVIOUS / NEXT
  ========================================= */

    if (pagerPrevButtonEl) {
      pagerPrevButtonEl.addEventListener('click', function () {
        goToPage(getCurrentPage() - 1, {
          scrollToSection: true,
        });
      });
    }

    if (pagerNextButtonEl) {
      pagerNextButtonEl.addEventListener('click', function () {
        goToPage(getCurrentPage() + 1, {
          scrollToSection: true,
        });
      });
    }

    /* =========================================
     INITIALIZE
  ========================================= */

    collabList.page = pageSizeForViewport();

    goToPage(1);

    /* =========================================
     RESPONSIVE PAGINATION
  ========================================= */

    let currentViewportTier = getViewportTier();

    window.addEventListener('resize', function () {
      const nextViewportTier = getViewportTier();

      if (nextViewportTier !== currentViewportTier) {
        currentViewportTier = nextViewportTier;

        collabList.page = pageSizeForViewport();

        goToPage(1);
      }
    });

    /* =========================================
     LIST.JS UPDATED EVENT
  ========================================= */

    collabList.on('updated', function () {
      /*
       * List.js has updated its items.
       * Now make sure only the correct
       * priority tag is visible.
       */
      requestAnimationFrame(function () {
        applyTagPriority();
      });

      renderPagerControls();
    });

    /* =========================================
     INITIAL TAG APPLICATION
  ========================================= */

    requestAnimationFrame(function () {
      applyTagPriority();
    });
  });




