        // Close the mobile menu on link click
        $(this).on('click', (e) => $menu_icon.trigger('click'));
      } else {
        // If parent items links are DISABLED
        if( ! parentClickable ){
          // Replace the URL with the # symbol
          $(this).attr('href', '#');
          // Open/close the submenu on link click
